window.UNF_REVIEW_CARDS={"t-1":{"title":"SMA 简单均线","line":"SMA把最近一段价格压成一条平均线，帮你回答‘最近整体是在抬高、降低，还是原地打转’。","points":[["看到什么","价格多次收在线上方，线也持续上斜：最近收盘通常高于平均水平，平均水平本身也在抬高。"],["它不代表","不代表下一根必涨，也不说明买入价格便宜。"],["常见误区","看到价格刚站上均线就以为马上大涨，结果在横盘震荡市里被价格来回穿线反复打脸。"]]},"t-2":{"title":"EMA 指数均线","line":"EMA也是把价格整理成平均线，但最近的收盘价分量更大，所以通常比同根数SMA更快转弯。","points":[["看到什么","EMA连续上移，收盘多数在线上：最新价格对平均值的拉动偏向上。"],["它不代表","不是所有持仓都盈利，更不是未来上涨保证。"],["常见误区","以为反应越快就越准，忽略了EMA对最新单根K线权重大，在震荡市里遇到一根突发长阳或长阴就会跟着猛拐，制造更多假拐头。"]]},"t-3":{"title":"WMA 加权均线","line":"WMA把最近N根价格按轻重求平均，常见线性版本让最新一根权重最大，越旧越轻。","points":[["看到什么","WMA比同周期SMA高，且二者向上：较新的价格平均更高，给它们更多权重会抬高结果。"],["它不代表","不是WMA发现了尚未发生的上涨。"],["常见误区","看到名字叫“加权均线”就默认是按成交量加权，其实标准WMA只按“时间远近（1、2、3…N）”加权，跟成交量毫无关系。"]]},"t-4":{"title":"SMMA/RMA 平滑均线","line":"SMMA/RMA让新价格一点点进入旧平均，常见RMA每根只给新价1/N的分量。","points":[["看到什么","价格急涨，RMA只略微抬高：新价格只占小部分，旧平均仍占大部分。"],["它不代表","不是涨幅很小，也不是指标坏了。"],["常见误区","不知道N期RMA的权重（1/N）只有N期EMA权重（2/(N+1)）的约一半，拿14期RMA和14期EMA直接比快慢。"]]},"t-5":{"title":"VWMA 成交量加权均线","line":"VWMA把最近N根价格按成交量加权：成交越多的那根，对均价影响越大。","points":[["看到什么","VWMA高于同周期SMA：窗口内较大成交量的价格总体偏高。"],["它不代表","不证明主力正在买入或未来一定涨。"],["常见误区","把滚动20根K线的VWMA和每天按交易日起点重新归零计算的VWAP（见本站「VWAP 成交量加权均价」一课）搞混。"]]},"t-6":{"title":"HMA 赫尔均线","line":"HMA用几次加权平均组合，让平均线在保持平顺的同时尽量少迟到。","points":[["看到什么","HMA连续上斜，价格也抬高低点：平滑方向和实际价格的近期改善一致。"],["它不代表","没有规定下一次回落一定守住该线。"],["常见误区","把“减少滞后”当成“没有滞后也没有假信号”，在横盘震荡市里跟着HMA的颜色切换来回买卖，结果因为HMA反应太快而被高频打脸。"]]},"t-7":{"title":"DEMA 双指数均线","line":"DEMA是‘双重指数移动平均’，但图上通常是一条合成线：2倍第一层EMA，减去第二次平滑的EMA。","points":[["看到什么","DEMA上行且高于普通EMA：较新的上涨通过减弱滞后的组合使它反应较快。"],["它不代表","不说明它看到更多市场数据。"],["常见误区","顾名思义地以为“双指数均线（DEMA）”就是在图上画一快一慢两条EMA看金叉死叉（那是见本站「MA Cross 均线交叉」一课）。"]]},"t-8":{"title":"TEMA 三指数均线","line":"TEMA把三层EMA按3×第一层−3×第二层+第三层合成一条价格线，目的是减少平均线的迟到。","points":[["看到什么","TEMA持续上行且收盘多在线上：近期价格拉动合成平均往上，方向相对一致。"],["它不代表","不证明继续上涨的概率已经确定。"],["常见误区","看到名字叫“三指数（Triple）”就以为是三条均线组合或“三重确认更稳当”，其实它是把滞后扣掉得更激进的单条快线，比普通EMA更容易被小回调刺穿。"]]},"t-9":{"title":"MA Cross 均线交叉","line":"双均线把一段短期平均价和一段较长期平均价放在一起，比较近期相对过去是否更强。","points":[["看到什么","短线由下穿上长线，之后两线抬高：近期平均改善，并开始带动更长平均。"],["它不代表","并不确定涨势起点，也不代表买入就不回撤。"],["常见误区","把“金叉（Golden Cross）”和“死叉（Death Cross）”当成百发百中的预测神旨，忽略了两根均线都是拿过去已经走完的K线算出来的，等交叉出现时价格往往已经涨了一大截、正好撞上短线回调。"]]},"t-10":{"title":"Moving Average Ribbon 均线带","line":"均线带把好几种长度的平均价画成一束，便于看短、中、较长的价格方向是否一致。","points":[["看到什么","10、20、40、80从上到下整齐排列且上行：较新的价格平均更高，不同窗口的方向暂时一致向上。"],["它不代表","四条同向不是四份独立预测，也不保证不会回撤。"],["常见误区","把4条或8条均线同向排列当成“多重独立指标共振”，不知道它们用的全是同一份收盘价数据，本质上只是同一个问题问了四个不同时间长度。"]]},"t-11":{"title":"RSI 相对强弱指数","line":"RSI把最近上涨与下跌的平均幅度转成0到100的分数。","points":[["看到什么","RSI高于70并继续停留：近期上涨幅度相对下跌明显占优，可能是强趋势。"],["它不代表","不是70%上涨或下跌概率，也不必马上回落。"],["常见误区","把70叫作“超买”、30叫作“超卖”之后就望文生义地当成自动卖出和自动买入按钮，结果在强势单边牛市里RSI刚上70就卖飞甚至反手做空被拉爆。"]]},"t-12":{"title":"MACD","line":"MACD把快EMA减慢EMA得到一条差值线，再用信号线平滑这个差；柱子显示两线之间还差多少。","points":[["看到什么","MACD在零线上，正柱逐根变长：快均价高于慢均价，且差值相对信号线进一步增强。"],["它不代表","不表示价格每根都上涨或下一根必涨。"],["常见误区","看到0线上方的绿柱（或红柱）开始缩短就以为价格已经在下跌，其实那只是上涨加速度放缓，在慢牛行情里柱子缩短后价格还能继续慢涨很久。"]]},"t-13":{"title":"Stochastic/KD 随机指标","line":"KD随机指标看收盘价位于最近最高与最低之间的什么位置：越靠近期顶部，读数越高；越靠底部，越低。","points":[["看到什么","K和D在80上方停留：平滑后的收盘位置持续靠近近期高端，可能是趋势强。"],["它不代表","不能保证马上下跌，也不是价格涨了80%。"],["常见误区","在强劲的单边上升趋势里，一看到K线和D线进入80以上死叉就急忙卖出甚至反手做空，结果遇到“高位钝化”一路踏空或爆仓。"]]},"t-14":{"title":"Williams %R 威廉指标","line":"Williams %R也衡量收盘在近期高低区间的位置，只是用0到−100的倒向刻度：接近0靠顶部，接近−100靠底部。","points":[["看到什么","%R高于−20，例如−10：收盘很靠近近期区间顶部，当前相对位置强。"],["它不代表","不是已经涨了90%，也不是必须马上卖。"],["常见误区","看漏负号把-20和-80的高低含义彻底颠倒，或者在部分把刻度改成0到+100正数的软件里没看清0和100哪头在上。"]]},"t-15":{"title":"CCI 顺势指标","line":"CCI衡量代表价格离近期平均有多远，并按平时偏离大小作调整。","points":[["看到什么","CCI从0升至+150并保持较高：价格向上偏离近期平均较明显，可能处于强势推进。"],["它不代表","不等于马上过热反转。"],["常见误区","拿RSI的固定0到100思维去套CCI，看到CCI到+100就以为到了天花板满分必跌，结果在突破行情里指标一路冲上+250把空单拉爆（其实原作者Lambert最初正是把突破+100当作顺势走强信号）。"]]},"t-16":{"title":"ROC 变动率","line":"ROC直接问‘现在比N根以前涨跌了百分之几’。","points":[["看到什么","ROC高于0并上升：相对滚动起点的涨幅扩大，所选跨度表现增强。"],["它不代表","不保证下一根上涨，也不代表每一天都上涨。"],["常见误区","看到ROC曲线从+10%往+3%下拐就以为价格已经见顶下跌，其实只要ROC仍在0%以上，当前价格依然比N根前高，甚至可能只是因为N根前的比较基数垫高了。"]]},"t-17":{"title":"Momentum 动量指标","line":"MTM或Momentum的常见差值版，用当前收盘减N根前收盘，直接显示相隔这段时间差了多少钱。","points":[["看到什么","差值为正且增加：现在比N根前高，跨这段的上涨距离扩大。"],["它不代表","不证明未来仍能维持同样涨速。"],["常见误区","不看副图中心轴是0还是100，把比值版显示的98（代表跌了2%）误当成差值版的+98大涨。"]]},"t-18":{"title":"PPO 价格百分比振荡器","line":"PPO把快慢EMA的差除以慢EMA，变成百分比。","points":[["看到什么","PPO为正并上升：快均价相对慢均价的优势扩大。"],["它不代表","不等于每根价格都在涨，更不是账户回报。"],["常见误区","以为把MACD换成了百分比形式的PPO就消除了均线滞后和横盘假信号，其实分子依然是12期与26期EMA之差，在箱体震荡市里金叉死叉照样会来回打脸。"]]},"t-19":{"title":"MFI 资金流量指数","line":"MFI把代表价格的上升下降与成交量结合，转成0到100的分数。","points":[["看到什么","MFI高于80并持续：近期向上那组的量价权重较占优。"],["它不代表","不能认定过高就必跌，也不是真实净流入比例。"],["常见误区","被名字里的“资金流量（Money Flow）”误导，以为它能统计主力资金净流入，不知道在它的算法里，只要今天典型价比昨天高哪怕0.01元，今天哪怕是冲高回落收假阴线，全天100%的成交额也都会被一刀切算成“100%正向资金流”。"]]},"t-20":{"title":"Bull/Bear Power 多空力量","line":"Bull/Bear Power用最高价与最低价分别减同一条EMA，观察一根K线两端离近期平均有多远。","points":[["看到什么","Bull正且增加，Bear由负接近0：上端离平均更远，下端也在靠近平均，整根价格范围可能抬高。"],["它不代表","不证明买方人数增加。"],["常见误区","不检查软件公式，把TradingView里将多空相加合成一条线的BBP（High+Low-2×EMA）当成单独的Bull Power来读。"]]},"t-21":{"title":"Bollinger Bands 布林带","line":"布林带画一条近期均价中线，再按价格分散程度画上下轨。","points":[["看到什么","带子收窄，价格活动范围也小：近期价格分散减小，市场暂时较安静。"],["它不代表","不告诉你下一步涨或跌，安静也可持续。"],["常见误区","不分青红皂白地把“碰上轨就做空、碰下轨就做多”当成铁律，在布林带收口后刚刚张口爆发单边突破时逆势摸顶抄底，结果价格一路沿着上轨或下轨单边推进（贴轨行走），造成严重亏损。"]]},"t-22":{"title":"Bollinger BandWidth 布林带宽","line":"布林带宽BBW把上轨与下轨之间有多宽变成数字，常用(上轨−下轨)÷中轨×100。","points":[["看到什么","BBW处于本资产历史低位：近期价格较集中，是相对安静状态。"],["它不代表","不保证马上突破，也不指定突破方向。"],["常见误区","把“带宽极低（Squeeze挤压）”直接等同于“抄底做多信号”，不知道波动率压缩之后向下崩盘暴跌同样会让带宽飙升。"]]},"t-23":{"title":"Bollinger %B 布林百分比","line":"布林%B把价格位于上下轨的哪里变成坐标：下轨是0，中间约0.5，上轨是1。","points":[["看到什么","%B持续接近1或超过1：价格靠近或位于近期上轨外，相对位置偏强。"],["它不代表","不证明马上下跌或已不可能再涨。"],["常见误区","看到%B突破1.0（收盘出上轨）就当成“超买极限”立刻做空，忽略了在强趋势突破初期，价格收在布林上轨之外（%B>1）恰恰是波动率向上爆发的特征。"]]},"t-24":{"title":"Donchian 唐奇安通道","line":"唐奇安通道把最近N根最高价和最低价画为上下边，中线取两者中点。","points":[["看到什么","上下轨都逐步抬高：近期最高和最低的活动范围在上移。"],["它不代表","不保证之后一直上涨。"],["常见误区","在默认包含当根K线的唐奇安通道里，傻等“K线跑到当根上轨上方”才算突破——因为当根上轨本身就包含当根最高价，K线永远只可能贴着当根上轨把轨顶高，必须看它是否突破“上一根K线时的上轨水平”。"]]},"t-25":{"title":"Keltner 肯特纳通道","line":"现代肯特纳通道通常以EMA为中线，以ATR的倍数决定上下距离。","points":[["看到什么","中线上行、收盘持续在上半带或上轨附近：平均方向偏强，近期价格也偏高于平均。"],["它不代表","碰上轨不自动等于应卖或价格见顶。"],["常见误区","分不清Chester Keltner 1960年代的早期原版（用10日典型价SMA加减10日高低差均值）与Linda Raschke后来推广的现代主流版（EMA加减ATR），在不同软件里没核对设置就直接套用。"]]},"t-26":{"title":"Moving Average Envelopes 均线包络线","line":"均线包络先画平均线，再向上和向下各偏移固定百分比。","points":[["看到什么","价格多在线上半、三条线持续上移：价格相对平均偏强，平均背景也在抬高。"],["它不代表","不保证碰上轨后会回落。"],["常见误区","把演示用的“3%或5%”当成放之四海而皆准的黄金比例，既拿去套每天只动0.5%的大盘指数，又拿去套每天动10%的小币种。"]]},"t-27":{"title":"ATR 平均真实波幅","line":"ATR衡量最近每根K线通常能活动多大，包含本根高低差和相对昨收的跳空。","points":[["看到什么","ATR比自身过去明显升高：近期单根真实活动范围扩大，平常的小距离更容易被穿过。"],["它不代表","不说明方向向上，也不等于必有反转。"],["常见误区","看到ATR曲线一路往上飙升就以为行情在走牛市大涨，其实市场恐慌暴跌时的真实波幅往往最大，ATR飙升最快。"]]},"t-28":{"title":"ATRP/NATR 百分比波幅","line":"ATRP/NATR常把ATR除以收盘价再乘100，回答‘通常的单根活动相当于价格的百分之几’。","points":[["看到什么","同一资产ATRP上升：平均真实活动占当前价格的比例变大。"],["它不代表","不表示价格上涨，价格下降也会使分母变小。"],["常见误区","没检查社区脚本的具体公式，把“先算ATR再除以最新收盘价”与“先算每根TR百分比再求平均”两个不同版本混在一起比。"]]},"t-29":{"title":"ADR 平均每日振幅","line":"ADR算过去若干天各自最高减最低，再求平均，描述‘一天内部通常走开多大距离’。","points":[["看到什么","今天已走范围远小于ADR：截至此刻日内活动比历史均值小，可能仍早或较安静。"],["它不代表","不意味着之后必须补足剩余距离。"],["常见误区","把“平均每日振幅（ADR）”当成“每日最大涨跌停板限制”，看到今天从低点往上已经走满了1倍ADR，就觉得今天肯定涨不动了而逆势重仓做空，结果遇到趋势突破日全天走出3倍ADR被拉爆。"]]},"t-30":{"title":"Standard Deviation 标准差指标","line":"价格标准差把最近一组价格离平均值有多分散概括成一个数。","points":[["看到什么","标准差上升：输入数据围绕其平均更分散，可能波动扩大或趋势拉开窗口价格。"],["它不代表","不说明未来价格向上。"],["常见误区","看到标准差曲线大幅向上翘起就以为是看涨信号，忽略了公式里“(价格-均价)²”一平方就把跌破均线的负号全消掉了，暴跌崩盘时的标准差同样会垂直飙升。"]]},"t-31":{"title":"Historical Volatility 历史波动率","line":"历史波动率HV看过去每根收益率有多不稳定，常再换成年化百分比。","points":[["看到什么","HV由低位升高：过去窗口内收益变化变得更分散，波动增强。"],["它不代表","不意味着价格上涨，也可能来自急跌。"],["常见误区","看到“年化历史波动率50%”就以为明年能赚50%，或者以为最大回撤不会超过50%，完全不懂它只是过去N天日收益率分散度的单位换算。"]]},"t-32":{"title":"Volume 成交量与均量线","line":"成交量记录一根K线内成交了多少股、币或合约；均量线是过去若干根的通常水平。","points":[["看到什么","上涨同时量明显高于均量：这段上涨伴随比平常更多成交，参与更活跃。"],["它不代表","不能证明只有买方获胜或接下来必涨。"],["常见误区","看到一根高耸的绿色（或红色）成交量柱就说“今天主力净买入几百万手”，忘了交易撮合的基本常识——每一笔成交的买单数量和卖单数量永远1:1相等，量柱颜色只取决于当根收盘价是否高于开盘价。"]]},"t-33":{"title":"RVOL 相对成交量","line":"相对成交量RVOL把当前量除以平常量，回答‘现在有平时几倍热闹’。","points":[["看到什么","RVOL大于1，例如2：当前量为所选基准约两倍，交易较活跃。"],["它不代表","不说明上涨，恐慌下跌也能放量。"],["常见误区","在日内分钟图上用普通滚动RVOL（拿开盘第一根K线和昨天收盘前或盘前清淡K线比），结果每天开盘都看到RVOL冲到5倍以上，误以为每天开盘都有重大异动。"]]},"t-34":{"title":"OBV 能量潮","line":"OBV按收盘涨跌给成交量记分：比上一根收得高就加整根量，低就减整根量，持平通常不变。","points":[["看到什么","价格与OBV都创近期新高：价格改善与涨跌日量的累计方向暂时一致。"],["它不代表","不证明下一次突破一定成功。"],["常见误区","看到OBV坐标轴写着“5000万”就以为场内有5000万资金净流入，不知道只要把图表起始时间往左多拉一年，因为起点不同，同一个位置的OBV数字就会完全变样。"]]},"t-35":{"title":"PVT 量价趋势","line":"PVT把每根收盘相对上一根的百分比变化乘成交量，再累计起来。","points":[["看到什么","价格上行且PVT也抬高：上涨的比例和量共同产生正累计，量价方向一致。"],["它不代表","不能确认某类资金进场或未来继续涨。"],["常见误区","把PVT的累计数字当成主力机构的资金净流入账本，不知道它只是拿收盘涨跌幅乘以成交量的数学乘积，根本无法区分是散户追高还是机构换手。"]]},"t-36":{"title":"PVO 成交量百分比振荡器","line":"PVO比较短期平均成交量比长期平均成交量高或低多少百分比。","points":[["看到什么","PVO高于0并上升：短期均量比长期均量大，活跃度优势扩大。"],["它不代表","不保证价格上升，恐慌也可很热闹。"],["常见误区","看外观长得和MACD一模一样（也有快慢线、0线和红绿柱），就把MACD的多空方向思维直接照搬过来，看到PVO金叉上穿0线就做多、死叉下穿0线就做空，忘了PVO只统计“成交量多不多”而不统计“价格涨没涨”——缩量慢牛时PVO可以在0下，而放量暴跌时PVO反而大涨。"]]},"t-37":{"title":"VWAP 成交量加权均价","line":"VWAP从选定起点累计价格乘量，再除累计量，得到这段成交的加权平均参考。","points":[["看到什么","价格持续在VWAP上方，线也上升：当前成交价格偏高于本期累计重心，新增成交也在抬高重心。"],["它不代表","不能保证VWAP会充当支撑或下一根上涨。"],["常见误区","在日线图（1D）上加载锚定周期为Session（日）的VWAP——因为每天只有1根日K线，每天都重置就会让VWAP直接贴在每根日K线的典型价上，完全失去加权平均意义。"]]},"t-38":{"title":"Parabolic SAR 抛物线指标","line":"抛物线SAR在价格上下画点，按一套加速规则跟踪当前算法方向。","points":[["看到什么","点持续在价格下方并逐步抬高：算法处于向上跟踪，跟踪参考位在提高。"],["它不代表","不保证价格不会突然跌穿或跳空越过。"],["常见误区","在占市场大多数时间的横盘震荡市里，照着SAR圆点每翻一次边就止损反手（Stop and Reverse），结果因为加速因子不断把点往价格上凑，在窄幅箱体里被连续左右抽耳光。"]]},"t-39":{"title":"Supertrend 超级趋势","line":"Supertrend用ATR和倍数在价格一侧画跟踪线，达到翻转条件后换到另一侧。","points":[["看到什么","线在下方逐渐抬高，收盘维持其上：算法维持向上跟踪，参考边界随走势抬高。"],["它不代表","不保证价格碰线会反弹。"],["常见误区","看到名字叫“超级趋势（Supertrend）”就以为是什么高深黑科技，其实它只是“中点加减3倍ATR再加单向棘轮”，在没有趋势的箱体震荡市里，每次等收盘突破3倍ATR翻多时刚好买在箱体顶部，等跌破3倍ATR翻空时刚好卖在箱体底部。"]]},"t-40":{"title":"Price Relative 相对表现","line":"价格相对强弱用A价格除以B价格，观察比值是升还是降。","points":[["看到什么","A涨10%，B涨5%，比值升：A这段相对跑赢B。"],["它不代表","不说明A未来继续领先或估值更便宜。"],["常见误区","分不清“相对跑赢（Relative Outperformance）”和“绝对盈利（Absolute Return）”，在熊市泥沙俱下时看到A/B比值线一路向上就高兴地满仓做多A，结果A只是比B少跌了一点，账户照样亏钱。"]]},"t-41":{"title":"ADX 趋势强度","line":"先回答行情有没有持续往一边走，再决定是否值得继续研究趋势。","points":[["看到什么","ADX 从 15 升到 28：过去观察窗口里，某一方向越来越占优势；返回主图才能知道哪一方向。"],["它不代表","不表示上涨了 28%，也不表示买方必胜。"],["常见误区","看到ADX数值很高就直接做多买入，忽略了猛烈暴跌时ADX同样会飙升，导致逆势接飞刀受损。"]]},"t-42":{"title":"DMI 趋向指标","line":"把行情拆成方向和强度两件事看：+DI、−DI 比较上推和下压，ADX 检查这种优势是否持续。","points":[["看到什么","+DI 高于 −DI，ADX 也上升：向上方向运动占优，方向性在增强，主图应进一步检查是否形成更高的高低点。"],["它不代表","不是保证上涨的金叉。"],["常见误区","在ADX低迷走平时把每次+DI与-DI交叉都当成趋势起点，结果在震荡区间内被左右打脸连续止损。"]]},"t-43":{"title":"Aroon 阿隆指标","line":"观察最近的新高和新低离现在有多久。","points":[["看到什么","Up 在高位，Down 在低位：新高出现得较近，最近低点相对久远，历史结构偏向上推。"],["它不代表","不表示上涨概率是 Up 那个百分数。"],["常见误区","把Aroon Up达到100当成涨幅巨大的证据，忽略了价格哪怕只微涨0.01元创出窗口新高也会让读数满格，从而高估上涨力度。"]]},"t-44":{"title":"Aroon Oscillator 阿隆振荡器","line":"把 Aroon 两条线的领先关系压缩成一条：Up 减去 Down。","points":[["看到什么","曲线由负转正，穿过零线：最近新高相对新低开始更有时间优势。"],["它不代表","不是价格穿越成本线，也不保证开始上涨。"],["常见误区","把振荡器读数接近+100当成超买做空信号，忽略了强势单边上涨中读数可以长期贴近+100，盲目摸顶容易亏损。"]]},"t-45":{"title":"Vortex 涡旋指标","line":"比较相邻 K 线之间向上与向下的移动哪一种更突出。","points":[["看到什么","VI+ 从下方穿到 VI− 上方并持续领先：最近向上方向的跨 K 线运动占优，值得继续观察上行结构。"],["它不代表","不是任何一次交叉都必须买入。"],["常见误区","在价格窄幅横盘时见交叉就操作，由于相邻K线高低点交替变化，指标会给出大量无效的假转向信号。"]]},"t-46":{"title":"Choppiness Index 震荡指数","line":"区分价格是在原地绕圈，还是比较顺地朝一边走。","points":[["看到什么","CHOP 高于 61.8 且维持高位：历史窗口更零碎、更曲折，追随方向容易被反复甩回。"],["它不代表","不等于价格波动很小。"],["常见误区","看到CHOP降到低位就直接做多，忽略了顺畅的单边下跌同样会让CHOP降到38.2以下，结果买在暴跌途中。"]]},"t-47":{"title":"Ichimoku 一目均衡表","line":"用同一张图观察近期均衡位置、中期均衡位置和较宽的价格区域。","points":[["看到什么","K 线整体位于云上方：相对这套中点区域，价格位置偏强；再看基准线与实际高低点是否抬升。"],["它不代表","云上也会发生急跌。"],["常见误区","把画在右侧空白处的未来云当成水晶球预测，不知道它只是把已经发生的中点数值往右挪了26格，盲目按云的形状赌未来涨跌。"]]},"t-48":{"title":"Williams Alligator 鳄鱼指标","line":"用三条快慢不同的平滑线，判断价格有没有从纠缠变成有序推进。","points":[["看到什么","三条线挤在一起、价格左右穿越：不同速度的参考价没有拉开，方向秩序较弱。"],["它不代表","不保证即将突破。"],["常见误区","看到三条线刚分开一点就重仓追进，忽略了平滑均线加向右平移本身有明显滞后，在震荡市里往往刚张嘴价格就已经见顶回落。"]]},"t-49":{"title":"KAMA 自适应均线","line":"观察一条会随行情是否顺畅而改变反应速度的平均线。","points":[["看到什么","KAMA 向上，价格多在其上方：经过自适应平滑后的方向偏上。"],["它不代表","线不是保证不会跌破的地板。"],["常见误区","把“自适应”当成“零滞后预测器”，在价格剧烈V型反转时指望KAMA立刻掉头，结果承受较大回撤。"]]},"t-50":{"title":"ALMA 阿诺勒古均线","line":"用加权后的平滑价格帮助看方向，同时尽量少被单根 K 线扰动。","points":[["看到什么","线持续上斜，收盘大多在线上：近期加权价格正抬高，价格也高于该参考。"],["它不代表","不保证回踩曲线就反弹。"],["常见误区","把线条的视觉丝滑感误认为预测准确度，看到ALMA拐头就以为趋势已经确立，结果在震荡市被慢半拍的拐点反复误导。"]]},"t-51":{"title":"McGinley Dynamic 麦金利动态线","line":"用一条追赶速度会随价格关系调整的动态线，看价格的大致方向和偏离程度。","points":[["看到什么","曲线上行，连续收盘位于线上：历史平滑方向与当前价格位置一致偏上。"],["它不代表","不保证线能托住下一次回落。"],["常见误区","把“减少滞后”曲解为“零滞后”，指望它在顶部和底部第一时间发出反转信号，结果在急转弯行情里依然反应慢半拍。"]]},"t-52":{"title":"LSMA 最小二乘均线","line":"看近期价格若用一条最贴近它们的直线概括，直线现在的末端在哪里。","points":[["看到什么","LSMA 连续上斜：近期拟合方向向上，越陡表示该设置下价格推进越快。"],["它不代表","未来价格不会被迫沿该线走。"],["常见误区","把对历史数据的“最小二乘最佳拟合”当成对未来价格的预测，遇到突发反转时被直线的惯性延伸误导。"]]},"t-53":{"title":"Linear Regression Channel 回归通道","line":"把近期价格大方向和离中心的远近分开看。","points":[["看到什么","通道向上，价格靠近上边：价格位于近期向上轨迹的较高一侧。"],["它不代表","不保证马上跌回中线。"],["常见误区","不知道回归通道会随新K线实时“重绘”（Repaint），拿静态历史图上看似完美的通道边界去实盘摸顶抄底，结果价格一路涨、通道一路跟着往上移。"]]},"t-54":{"title":"Linear Regression Slope 回归斜率","line":"把近期拟合直线的上斜或下斜量化，观察方向和速度有没有改变。","points":[["看到什么","原始斜率 +0.5 升到 +0.9：同样窗口和日线设置下，向上的拟合推进变快。"],["它不代表","不等于明天必涨 0.9。"],["常见误区","跨品种直接比较原始斜率数值，不知道50000美元的资产和1美元的资产算出的原始斜率差上万倍，从而得出荒谬的强弱结论。"]]},"t-55":{"title":"Linear Regression R² 回归决定系数","line":"检查用直线概括这段价格到底合不合适。","points":[["看到什么","R² 接近 0.9：这段价格相对像一条直线，拟合能解释较多变化。"],["它不代表","不是未来预测有 90% 胜率。"],["常见误区","把R²读数当成上涨概率或胜率，看到0.85就满怀信心做多，没看清主图其实是一路整齐阴跌。"]]},"t-56":{"title":"Correlation Coefficient 相关系数","line":"比较两个序列在过去窗口里是否一起升降。","points":[["看到什么","系数接近 +0.9：该窗口两序列有较强同向线性关系。"],["它不代表","不表示一方涨 1%，另一方必涨 0.9%。"],["常见误区","把“相关性高”当成“因果关系”，盲目看着A品种涨就去买B品种，忽略了两边可能只是受同一消息短暂带动，随时会脱钩走出独立行情。"]]},"t-57":{"title":"StochRSI 随机 RSI","line":"判断 RSI 这把涨跌力度尺，目前在它自己最近的范围里靠上还是靠下。","points":[["看到什么","两线靠近 100 或 1：RSI 处于自己最近范围较高位置，短期相对动量偏热。"],["它不代表","不表示价格马上下跌或涨了 100%。"],["常见误区","把StochRSI超过80或低于20直接当成价格见顶或见底的铁证，忽略了它只是对RSI再做一次区间放大，敏感度极高，在普通横盘里也会频繁撞顶撞底。"]]},"t-58":{"title":"ConnorsRSI 康纳斯 RSI","line":"把短期涨跌力度、连涨连跌的持续性、当天变化相对历史的罕见程度放在一起，识别短期伸展。","points":[["看到什么","读数接近 90：三个短期维度合起来很靠上，可能已有较明显上伸。"],["它不代表","不是 90% 概率明天跌。"],["常见误区","把普通RSI的70和30直接照搬到CRSI上，由于CRSI使用的周期极短（3和2），读数经常大起大落，用70/30会导致信号泛滥。"]]},"t-59":{"title":"CMO 钱德动量","line":"比较观察窗口中上涨总幅与下跌总幅，了解哪一边累计推进更多。","points":[["看到什么","CMO 在正区持续走高：上涨总幅相对下跌总幅的优势扩大。"],["它不代表","不表示每根 K 线都上涨。"],["常见误区","看到CMO达到+50或-50就立刻反向摸顶抄底，忽略了在单边强趋势里上涨总和持续远超下跌总和，指标会长期停留在高区。"]]},"t-60":{"title":"True Strength Index 真实强弱指数","line":"把逐根涨跌平滑后，与全部变化幅度比较，观察净动力朝上还是朝下。","points":[["看到什么","TSI 在零线上且上升：平滑后的净上行变化占优，并在增强。"],["它不代表","不代表未来涨幅就是 TSI 数字。"],["常见误区","以为线条越平滑就越完美，忽略了25和13两层平滑带来的滞后，在短促的急涨急跌行情里等到TSI金叉时行情往往已经走完大半。"]]},"t-61":{"title":"TRIX","line":"看经过三次平滑的价格，最近变化速度是正还是负。","points":[["看到什么","TRIX 为正且上升：平滑价格仍上涨，而且变化速度加快。"],["它不代表","不保证原始价格每根上涨。"],["常见误区","把“线条安静无毛刺”等同于“稳妥无风险”，忽略了三次平滑累加的严重滞后，在V型急跌行情里等到TRIX下穿零线时价格早已大幅回撤。"]]},"t-62":{"title":"Ultimate Oscillator 终极振荡器","line":"同时考虑短、中、长三个窗口的价格推动，减少只看一段长度的片面。","points":[["看到什么","读数在 70 以上：综合价格推动靠近近期较高一侧，状态偏热。"],["它不代表","不意味着必须马上下跌。"],["常见误区","看到中文名叫“终极振荡器”就以为它是包治百病的万能神器，单凭一个指标重仓下注。"]]},"t-63":{"title":"Awesome Oscillator/AO","line":"比较较短与较长的高低中点平均价，观察短期方向相对长期是否增强。","points":[["看到什么","柱在零线上且越来越高：短期均价领先长期均价，领先程度扩大。"],["它不代表","不表示每一根实际 K 线都上涨。"],["常见误区","把柱子颜色和正负号搞混，在0线下方深处看到第一根绿柱就以为已经进入多头趋势，其实当时5周期均价依然远低于34周期均价。"]]},"t-64":{"title":"SMI 随机动量指数","line":"看收盘位于近期高低范围的上半还是下半，再把变化平滑。","points":[["看到什么","SMI 明显为正：平滑后的收盘位置偏近期范围上半侧。"],["它不代表","不表示价格上涨了相同百分比。"],["常见误区","在指标库搜索时把Stochastic Momentum Index、SMI Ergodic和StochRSI三个不同公式的指标混为一谈，乱套参数和参考线。"]]},"t-65":{"title":"SMI Ergodic 遍历指标","line":"用平滑后的净涨跌与总涨跌幅比较，读出方向动力，并用慢信号线观察动力有没有改善。","points":[["看到什么","主线为正且在信号线上方：净上行动力占优，且比慢参考更强。"],["它不代表","不能保证价格继续涨。"],["常见误区","被名字里的“SMI”误导，直接把上一课随机动量指数的±40参考线搬过来用，遇到显示-1到+1小数的脚本完全看懵。"]]},"t-66":{"title":"Relative Vigor Index 相对活力指数","line":"比较收盘相对开盘的净推进，和每根 K 线整个活动范围，观察一段时间是否经常朝同一边收盘。","points":[["看到什么","主线持续为正：近期收盘相对开盘的向上推进占优。"],["它不代表","不保证收盘比昨天更高，跳空也可能影响实际涨跌。"],["常见误区","在指标栏只输入缩写“RVI”，结果误加了完全不同的Relative Volatility Index（见本站「Relative Volatility Index 相对波动指数」一课）。"]]},"t-67":{"title":"Relative Volatility Index 相对波动指数","line":"比较向上与向下阶段的价格波动哪一侧更占优势。","points":[["看到什么","读数持续高于 50：按该算法，向上方向的波动贡献更占优势。"],["它不代表","不是未来上涨概率高于 50%。"],["常见误区","望文生义地把“相对波动指数”当成衡量市场总风险大小的波动率指标（如VIX或ATR），其实它是衡量上行波动与下行波动谁占优的方向性比例。"]]},"t-68":{"title":"RCI 排名相关指数","line":"检查价格高低排名是否与时间先后排列一致。","points":[["看到什么","RCI 接近 +100：该窗口后来的价格普遍排在更高位置，顺序较整齐。"],["它不代表","不表示已经上涨 100%。"],["常见误区","把RCI接近+100当成涨幅巨大或严重超买，忽略了小碎步微涨只要顺序不乱就能拿到满分，而一旦出现一根大阴线吞没前几根微涨就会亏钱。"]]},"t-69":{"title":"Fisher Transform 费舍尔变换","line":"把价格在近期范围里特别靠边的情况放大，让动量转弯更容易看见。","points":[["看到什么","Fisher 在明显正高位继续上行：价格持续偏向近期范围的上侧，局部状态较极端。"],["它不代表","高位不保证下一根下跌。"],["常见误区","死背某本书上写的“+1.5或+2.0就是绝对顶部”，不知道费舍尔变换理论上没有固定上下限，不同品种和不同平滑实现下的极值范围差异很大。"]]},"t-70":{"title":"DPO 去趋势价格振荡器","line":"先减去较慢的价格背景，再回看局部价格高低循环。","points":[["看到什么","DPO 在零线上方形成波峰：对应历史价格高于被扣除的背景，可用于回看局部高位。"],["它不代表","不保证当前价格马上见顶。"],["常见误区","开启Centered（居中）模式后看到副图波峰波谷和主图高低点对得无比精准，误以为找到了圣杯，不知道那是用了未来11根K线数据算出的事后均线往回画的结果，实时最新K线处根本画不出来。"]]},"t-71":{"title":"KST 确然指标","line":"把四种长短的涨跌速度合成一条动量线，减少只看单一窗口的片面。","points":[["看到什么","KST 正值并高于信号线：综合涨跌速度偏上，且近期相对慢参考更强。"],["它不代表","不能保证所有四个分量都为正。"],["常见误区","看到名字叫“确然指标（Know Sure Thing）”就以为获利不赔，连原作者Pring都强调没有任何指标能做到百分百确定。"]]},"t-72":{"title":"Pring Special K","line":"同时汇总很多短、中、长窗口的涨跌速度，观察更宽时间范围内的动力背景。","points":[["看到什么","主线整体向上且高于慢信号线：多个时间层次合成的动力在改善。"],["它不代表","不代表每个短周期都上涨。"],["常见误区","在剛上市几个月的新品种上加载Special K，看到副图一片空白还以为软件坏了，不知道默认参数需要至少725根K线的历史数据。"]]},"t-73":{"title":"PMO 价格动量振荡器","line":"观察百分比涨跌速度经过两次平滑后，是偏上、偏下还是放慢。","points":[["看到什么","PMO 为正且上升：平滑后的向上变化速度占优并增强。"],["它不代表","不保证价格每根都涨。"],["常见误区","分不清“跌得慢了”和“开始涨了”，看到PMO在负值深水区向上拐头并金叉信号线就重仓抄底，结果遇到绵绵不断的阴跌行情被套牢。"]]},"t-74":{"title":"Coppock Curve 科波克曲线","line":"在较长时间范围观察深度低迷后的动量是否回暖。","points":[["看到什么","曲线在负区形成低点后上弯：长期下行速度开始缓和，是原始思路关心的回暖过程。"],["它不代表","不保证最低价已经出现。"],["常见误区","脱离原作者专为月线图（11个月与14个月）设计的长期研究背景，生搬硬套到5分钟图上频繁买卖。"]]},"t-75":{"title":"MACD-V","line":"把快慢均价之差放到日常波动尺度里比较。","points":[["看到什么","主线为 +100：快均价高于慢均价，差约为当前一份 ATR。"],["它不代表","不表示涨了 100% 或要涨一倍。"],["常见误区","把“MACD-V”里的“V”当成Volume（成交量），在指标库里误选了成交量加权MACD（VW-MACD），导致看的完全是另一套东西。"]]},"t-76":{"title":"Mass Index 质量指数","line":"观察每根 K 线最高到最低的活动范围是否先扩大再缓和。","points":[["看到什么","指标上穿 27：在常见参数下出现较明显的范围扩张阶段。"],["它不代表","不表示行情方向向上。"],["常见误区","不看价格方向就单凭“上27回落26.5”直接反向开仓，忽略了质量指数公式里只有“最高价减最低价”，连收盘价涨跌都没算进去，本身根本没有多空方向。"]]},"t-77":{"title":"Accumulation/Distribution 累积派发线","line":"看成交量是否经常伴随着靠上端或靠下端的收盘，并把结果累积。","points":[["看到什么","ADL 连续抬升：近期加权成交量偏向上端收盘的贡献较多。"],["它不代表","不证明净资金正以同等数量流入。"],["常见误区","把指标名称里的“累积/派发”当成机构主力暗中建仓或出货的实锤证据，不知道它只是拿当根K线的最高、最低、收盘和成交量算出来的数学公式。"]]},"t-78":{"title":"CMF 蔡金资金流","line":"把最近窗口的加权成交量，与同一窗口全部成交量比较，观察收盘偏上还是偏下的量价贡献。","points":[["看到什么","CMF 持续为 +0.2：窗口加权成交量为正，占总成交量约两成的这个数学比值。"],["它不代表","不是净流入资金 20%。"],["常见误区","看到名字叫“资金流（Money Flow）”就以为它在监控银行转账或大户钱包，其实每一笔成交有买必有卖，它只是看收盘价靠近当根最高还是最低。"]]},"t-79":{"title":"Chaikin Oscillator 蔡金振荡器","line":"观察 ADL 这条量价累计线的变化速度，而不是只看累计线升到多高。","points":[["看到什么","读数为正且上升：ADL 快平均高于慢平均，领先差距扩大，量价上侧倾向的速度较强。"],["它不代表","不表示真实资金净流入同等金额。"],["常见误区","在图上同时放ADL、CMF和蔡金振荡器三个指标，看到三个都翻红或翻绿就信心爆棚重仓梭哈，不知道它们全都是由“收盘在高低区间的位置×成交量”算出来的同源指标，要错会一起错。"]]},"t-80":{"title":"Klinger Oscillator 克林格振荡器","line":"把成交量与价格方向、范围变化结合，再比较快慢变化，观察量价推动的节奏。","points":[["看到什么","主线在零线上并领先信号线：量价力快平均占优，近期也较慢参考更强。"],["它不代表","不保证价格随后上涨。"],["常见误区","把公式里的“成交量力度（Volume Force）”当成主力机构的真实资金账单，忽略了不同交易所或数据源的成交量统计口径差异会让KVO算出不同结果。"]]},"t-81":{"title":"Elder Force Index 艾尔德力度指数","line":"同时考虑涨跌的距离和参与成交的数量：价格变得多、量也大，力度值就更大。","points":[["看到什么","正值扩大：按该平滑口径，上涨乘量的贡献增强。"],["它不代表","不证明每笔成交都是主动买单。"],["常见误区","跨品种或跨周期直接对比EFI的坐标轴数字，不知道价格1000元的品种与价格1元的品种、或者成交量单位不同的市场算出的数字根本不在一个量级。"]]},"t-82":{"title":"EOM/EMV 简易波动指标","line":"观察价格中点移动了多少、范围多宽、成交量多少，判断同样移动是否花了较少成交量。","points":[["看到什么","较大的正值：在该算法中，上移较明显、相对量的阻力较小。"],["它不代表","不保证买入后容易卖出，也可能是薄市场跳动。"],["常见误区","把“无量空涨导致的高EOM”当成绝对好事，忽略了在缺乏买卖盘深度的冷清市场或垃圾币里，少量资金能轻松拉高价格，反过来少量卖单也能瞬间把价格砸穿，买入后根本卖不出去。"]]},"t-83":{"title":"PVI 正量指标","line":"单独记录放量那些时段的价格表现。","points":[["看到什么","放量且收盘上涨，PVI 抬升：被筛中的放量时段产生正回报贡献。"],["它不代表","不是所有参与者都获利。"],["常见误区","死背老书上“PVI代表散户非理性跟风、NVI代表机构聪明钱”的教条，不知道现代市场里机构突破建仓、量化程序执行和ETF申购同样会制造巨大成交量，公式根本无法识别交易者身份。"]]},"t-84":{"title":"NVI 负量指标","line":"单独记录缩量那些时段的价格表现。","points":[["看到什么","缩量上涨，NVI 上升：被筛选的缩量时段贡献正回报。"],["它不代表","不证明机构正在悄悄买入。"],["常见误区","把“负量（Negative Volume）”望文生义地理解成“主力净卖出量”或负数成交量。"]]},"t-85":{"title":"BOP 均势指标","line":"看每根从开盘到收盘留下的净推进，占整根高低活动范围多少。","points":[["看到什么","BOP 接近 +1：该根向上净推进占范围很大，收盘相对开盘强。"],["它不代表","不是买方占全部成交的 100%。"],["常见误区","看到BOP冲到+0.9或+1.0就以为多头力量无比强大，忽略了它算的只是“实体除以全长”的比例——一根全天只波动1分钱的光头小阳线BOP也是+1.0，しかも公式里根本没有成交量。"]]},"t-86":{"title":"Relative Volume at Time 同时段相对成交量","line":"同时段相对成交量帮你回答：现在比过去同一个时间段热闹多少？","points":[["看到什么","读数明显高于1：这个时间的交易比所选历史样本更活跃。"],["它不代表","不代表买家比卖家多，也不代表价格必涨，每笔成交都有双方。"],["常见误区","看到相对成交量飙到2倍或3倍就直接做多，忽略了恐慌性抛售暴跌时的同时段成交量同样会放大好几倍。"]]},"t-87":{"title":"TTM Squeeze 波动挤压","line":"TTM Squeeze把两个问题分开：价格是否比平时更安静，以及安静之后向哪边加速。","points":[["看到什么","连续出现挤压中标记：所选公式识别到波动受压缩。"],["它不代表","不保证很快爆发，也无法仅凭圆点知道向上还是向下。"],["常见误区","看到0线上亮起挤压红点就迫不及待提前满仓做多，不知道挤压只代表“现在很安静”，既可能安静好几十根K线，也可能最后向下暴跌释放。"]]},"t-88":{"title":"Ulcer Index 溃疡指数","line":"Ulcer Index中文常叫溃疡指数，专门衡量价格跌离近期高点的压力。","points":[["看到什么","曲线从低位连续抬高：最近离高点的下跌更深或持续更久。"],["它不代表","不代表下一根一定继续跌，也不提供下跌结束日期。"],["常见误区","看到溃疡指数从高位回落就以为价格通常已经大涨创新高，忽略了“窗口滚动效应”——如果价格在大跌后一直死水微澜横盘，等14根K线之前的那个老高点移出计算窗口，基准高点变低，UI也会自动大幅回落。"]]},"t-89":{"title":"Chandelier Exit 吊灯止损","line":"吊灯止损帮助已经持仓的人思考：如果价格从近期高点退回多少，我要重新检查继续持有的理由？","points":[["看到什么","价格在多头退出线上方并拉出新高：按这套退出参考，多头持有条件尚未被触及。"],["它不代表","不代表此刻适合新买入，更不保证会再创新高。"],["常见误区","把图表软件上画出来的吊灯线当成已经在交易所下好的真实止损单，结果关掉电脑去睡觉，遇到暴跌账户根本没有自动平仓。"]]},"t-90":{"title":"Chande Kroll Stop 钱德克罗止损","line":"Chande Kroll Stop把近期价格范围和波动大小整理成两条退出参考线。","points":[["看到什么","价格高于两条线：当前价格相对这组参考处在较强的一侧，适合继续检查多头持有条件。"],["它不代表","不是线在下方就一定买，也不等于价格无法下穿。"],["常见误区","在价格夹在两条线中间横盘拉锯时，把每次碰上线或碰下线都当成反手开仓信号，结果在窄幅区间内被左右止损。"]]},"t-91":{"title":"ATR Trailing Stop 跟踪止损","line":"ATR跟踪止损用近期常见的价格晃动给持仓留空间，并在价格有利发展时移动退出参考。","points":[["看到什么","上涨时保护线逐步抬高：该版本正在把退出参考向更高价格收紧。"],["它不代表","不保证线能守住，也不表示每次抬高都需要加仓。"],["常见误区","不知道市面上同名脚本有的从最高价减ATR（类似吊灯止损）、有的从收盘价减ATR，不看源码就直接混用。"]]},"t-92":{"title":"Volatility Stop 波动止损","line":"波动止损是一类退出方法：最近价格晃得大，留的缓冲通常更宽；晃得小，缓冲通常更窄。","points":[["看到什么","价格沿同一方向走，线持续跟随：这段历史趋势尚未触发所选翻转条件。"],["它不代表","不代表未来仍会沿该方向，更不表示可以不设退出计划。"],["常见误区","只看波动止损帮忙把高波动品种的止损位拉宽了3倍，却不把买入仓位缩小到1/3，结果一旦打止损直接亏掉平时3倍的本金。"]]},"t-93":{"title":"Anchored VWAP 锚定 VWAP","line":"锚定VWAP是在你指定的起点之后，计算按成交量加权的平均价格。","points":[["看到什么","价格连续收在线上且线向上：这段成交平均被抬高，现价仍在其上。"],["它不代表","不证明所有买家都盈利，也不保证触线必反弹。"],["常见误区","在历史图上拿着锚定VWAP鼠标到处乱点，直到找到某一根K线画出来的线刚好托住后来的低点，就以为发现了神奇规律（典型的事后凑图）。"]]},"t-94":{"title":"Pivot Points 标准枢轴点","line":"枢轴标准点用上一段已经完成的高、低、收盘价，为下一段画一组水平路标。","points":[["看到什么","价格在P上方交易：现价相对这组中心参考较高，可作当天位置背景。"],["它不代表","不是今天必涨，也不表示回落到P必须买。"],["常见误区","不知道枢轴点有Traditional（传统）、Fibonacci（斐波那契）、Camarilla（卡玛利拉）等好几种完全不同的计算公式，跟别人讨论R1/S1时鸡同鸭讲。"]]},"t-95":{"title":"Pivot Points High/Low 高低点枢轴","line":"局部高低点指标把一段价格里的小山峰和小山谷标出来。","points":[["看到什么","已确认高点与低点都逐步抬高：按这组过滤尺度，历史价格结构偏向上行。"],["它不代表","不保证下一个低点仍抬高，更不代表所有更小周期也向上。"],["常见误区","看着静态历史图上每一个波段最高点都整整齐齐顶着一个High标签、每一个最低点都标着Low标签，就误以为这个指标能百发百中抓顶抄底，完全不知道那是等右边走完Right根K线后“往回画（Back-painting）”上去的。"]]},"t-96":{"title":"Fibonacci 斐波那契回撤/扩展","line":"斐波那契回撤与扩展把一段明确的涨跌分成固定比例，帮你回答“价格回头走到了原路程的几成，或顺势冲出相当于原路程的几倍”。","points":[["看到什么","上涨回调到0.382或0.618附近减速，K线实体不再下移：说明回吐在常见比例刻度附近暂遇买盘承接，回调仍在原波段内。"],["它不代表","不代表0.618是铁底，也不说明价格马上会创新高。"],["常见误区","在0.382、0.5、0.618每一条线上都挂满左测逆势盲单，不知道单边强下跌会像切豆腐一样把所有比例线一根接一根全部跌穿。"]]},"t-97":{"title":"Williams Fractals 威廉分形","line":"威廉姆斯分形把一小组K线中的局部峰谷标出来。","points":[["看到什么","后一个已确认高点和低点均更高：这组局部转折反映价格台阶向上。"],["它不代表","不意味着每个下方箭头都是可盈利买点。"],["常见误区","看着历史图上每个小尖顶都有一个漂亮的分形箭头，就以为见下箭头买、见上箭头卖能获利，不知道箭头出来时价格已经往反方向走了整整2根K线。"]]},"t-98":{"title":"ZigZag 之字转向","line":"ZigZag把零碎波动过滤掉，再用折线连接较大的转折，让你看清价格走过的大轮廓。","points":[["看到什么","小反弹没有产生新折线：幅度或转折根数未满足过滤条件，被省略。"],["它不代表","不表示市场没有发生那次反弹。"],["常见误区","把ZigZag当成实时买卖信号指标，不知道它的最后一段是典型的“动态重绘（Repainting）”——历史图上看起来每一折都神准无比地抓到了最高点和最低点，那是因为不准的中间过程全被擦掉了。"]]},"t-99":{"title":"Volume Profile 成交量分布","line":"成交量分布（Volume Profile）把选定时间段的成交量按“价格高低”横向累加，帮你回答“过去这段时间大家最密集在哪个价位换手”。","points":[["看到什么","价格在VAL与VAH之间来回折返，多次在POC附近减速：说明市场暂认可选定窗口的70%高成交区，买卖双方仍在旧活跃带内拉锯。"],["它不代表","不代表VAL跌不破，也不代表碰到POC就会精准反弹。"],["常见误区","把高成交量区（HVN）和POC当成绝对不会跌破的铁底，不知道那里只是过去多空分歧换手最密的地方，一旦市场情绪转向，价格完全可以穿过POC并在另一处建立新价值区。"]]},"t-100":{"title":"TPO/Market Profile 市场轮廓","line":"TPO把交易日按固定时间块切片，记录每个价位被多少个时间段访问过，帮你回答“价格在哪里停留时间最久、在哪里一闪而过”。","points":[["看到什么","字母在中间价位堆得很宽、上下两端很短，呈钟形分布：说明全天多数时间段都在中间价格带反复逗留，多空处于日内相对平衡。"],["它不代表","不代表次日还会继续横在该区间，也不说明这里成交量最大。"],["常见误区","把TPO字母堆积宽度等同于成交量大小，不知道在窄幅死水微澜的午盘横盘期，价格在101元耗了3个小时会堆出6个字母（其实成交量极小），而在尾盘放巨量突破105元的半小时里只有1个字母（其实成交量全天最大）。"]]},"t-101":{"title":"Volume Delta 成交量差值","line":"成交量差额Volume Delta比较一根K线里被归为正向和负向的成交量。","points":[["看到什么","价格上涨、差额偏正：这一根价格与所选分类中的正向活动大致同步。"],["它不代表","不保证下一根继续涨。"],["常见误区","以为正Delta就等于价格往往上涨，忽略了当上方挂着巨额被动限价卖单时，大量主动市价买单撞上去会让Delta呈现巨大正数，但价格却被被动卖单死死按住甚至掉头下跌（吸收现象）。"]]},"t-102":{"title":"CVD 累积成交量差值","line":"累计成交量差额CVD把一根根差额记在同一本账上，看指定时间内正向还是负向活动更持续。","points":[["看到什么","同一累计段内价格和CVD都新高：价格与累计分类量在这段里同向增强。"],["它不代表","不是随后仍会涨的承诺。"],["常见误区","在开启按日（Session）或按周重置的CVD图上，看到交界处曲线突然从+5000垂直掉回0，吓得以为发生了主力大砸盘，不知道那只是新一天从0重新开始记账。"]]},"t-103":{"title":"Volume Footprint 成交足迹图","line":"成交足迹图（Volume Footprint）把单根K线内部剖开，按价格格显示每一格的卖方成交量与买方成交量，帮你回答“这根K线内部哪个价位交手最密、哪边更主动”。","points":[["看到什么","价格上推，连续几格右列买量远大于左列卖量，且收盘在高格：说明上涨中按平台分类的主动买单持续吃掉上方卖单并守住涨幅。"],["它不代表","不代表下一根K线买方还会继续进攻，也不证明是机构建仓。"],["常见误区","看到某一格显示“买量500”就断定是某一个机构大户一笔买进的，不知道那500手可能是几百个散户小单在几分钟内累加出来的，而且每一笔买单对面都有等量的限价卖单成交。"]]},"t-104":{"title":"Advance/Decline 腾落线","line":"腾落线看的是一群股票有没有广泛参与涨跌，不是单只股票的K线。","points":[["看到什么","指数与腾落线一起创新高：指数上涨同时，多数股票参与的累计情况也较强。"],["它不代表","不保证所有股票都涨或接下来继续上涨。"],["常见误区","在单只股票或单个币种图上以为腾落线是在数“这只股票的阳线K线根数减阴线根数”，不知道它是统计整个交易所成百上千只股票涨跌家数的市场广度（Breadth）指标。"]]},"t-105":{"title":"New Highs/New Lows 新高新低广度","line":"新高新低家数统计一群股票里，有多少创指定时期的新高、有多少创新低。","points":[["看到什么","新高家数连续扩张且新低很少：更多成员达到所选期间高位，强势参与在扩散。"],["它不代表","不等于上涨不会结束，也不代表此刻新买都合适。"],["常见误区","拿不同规模市场的原始家数直接比大小——比如看到A市场有100家创新高、B市场有80家创新高就说A更强，忘了A市场有4000只股票而B市场只有200只股票。"]]},"t-106":{"title":"Percent Above MA 均线上方股票占比","line":"均线上方家数占比看一群股票里，多少站在各自的平均价格之上。","points":[["看到什么","占比从30%逐步升至60%：越来越多成员高于自己的均线，参与范围在改善。"],["它不代表","不等于这些股票已经上涨30%，也不保证改善持续。"],["常见误区","把20日均线上方占比、50日占比和200日占比混为一谈——20日占比跌到15%一年可能出现好几次，而200日占比跌到15%往往只在罕见大熊市才出现。"]]},"t-107":{"title":"Open Interest 未平仓量","line":"未平仓量（Open Interest，简称OI）统计期货或永续合约市场里“当前尚有多少张已开立但未平掉的生效合约”，帮你回答“场内合约总规模是在增加还是减少”。","points":[["看到什么","价格明显上涨或下跌，按币数统计的OI也同步持续上升：说明新开立的合约数量超过平仓数量，场内总持仓规模在扩大。"],["它不代表","不代表新开仓位“全是多头”，每新增1张合约都同时含1多1空。"],["常见误区","说出“未平仓量OI大涨说明今天多头买盘远大于空头卖盘”这种外行话——在任何衍生品市场，每一张未平仓合约都必定有1份多头和1份空头严格1:1配对，OI增加1万张代表同时增加了1万张新多单和1万张新空单。"]]},"t-108":{"title":"Funding Rate 资金费率","line":"资金费率（Funding Rate）展示永续合约每隔固定时间在多空持仓者之间互付的费用比例，帮你回答“当前合约相对现货偏贵还是偏便宜，以及持仓跨结算点需付出还是收到费用”。","points":[["看到什么","资金费率长期在基准值（如+0.01%）附近温和波动：说明永续合约与现货价格差距不大，处于常规小幅正溢价状态。"],["它不代表","不代表价格不会波动，也不代表多头没有持仓成本。"],["常见误区","算持仓成本时只拿自己的本金确保金去乘资金费率，忘了10倍或20倍杠杆会把资金费损耗同步放大10倍或20倍，拿了半个月发现本金被资金费啃掉一大块。"]]},"t-109":{"title":"Long/Short Accounts Ratio 多空账户比","line":"多空账户比（Long/Short Accounts Ratio）把样本里“净做多账户人数”除以“净做空账户人数”，帮你回答“被统计的交易者里，站多头的账户多还是站空头的账户多”。","points":[["看到什么","多空账户比升至2.0以上，而价格却在持续阴跌：说明该样本下净做多账户人数是净做空的2倍以上，不少小账户在下跌中抄底。"],["它不代表","不代表多头总资金比空头多，也不代表人多的一方会把价格推高。"],["常见误区","说出“多空比高达2.5说明市场上多单合约比空单合约多出1.5倍”这种违背交易撮合基本原理的话——每一张多单都必须有对手方的一张空单才能存在，全市场多空总持仓张数永远严格相等。"]]},"t-110":{"title":"Liquidations 已发生强平数据","line":"已发生强平数据（Liquidations）记录因确保金不足被平台强制平仓的合约金额或数量，帮你回答“刚才这波急涨急跌里，有多少被动爆仓的杠杆仓位被清退”。","points":[["看到什么","价格快速下挫留长下影线，副图拉出巨大多头强平柱且OI锐减：说明下跌触发大量多单强平，系统集中执行被动卖出平仓，释放了一批杠杆多头。"],["它不代表","不代表多头已全部爆完，也不代表价格不会再破前低。"],["常见误区","搞反强平的买卖方向——看到“多头强平5000万美元”还以为是系统买进5000万托底，其实多头被爆仓是被迫把多单“市价卖出平仓”，反而会砸穿盘口加速下跌。"]]},"t-111":{"title":"支撑与阻力","line":"支撑与阻力把过去价格多次停下并折返的区域标在图上，帮你回答“历史上买卖双方常在哪一带发生明显争夺或转向”。","points":[["看到什么","价格回落到曾两次反弹的99至101元支撑带，跌势放缓并收下影线：说明价格再次进入历史买盘活跃区，短期下跌暂遇承接。"],["它不代表","不代表这次也会大涨，支撑被多次测试后同样可能跌穿。"],["常见误区","把支撑位当成精确到小数点后两位的铁板，结果价格盘中刺到99.50元把止损扫掉后立刻拉回105元。"]]},"t-112":{"title":"趋势线与通道","line":"趋势线与通道用斜线连接依次抬高的波段低点并配平行边线，帮你回答“近期价格沿怎样的斜率推进，当前是否冲出或跌破原有斜坡”。","points":[["看到什么","价格沿上升通道运行，第三次回调靠近下轨时止跌抬升：说明“低点逐步抬高”的推进斜率暂得维持，买盘仍按原节奏承接。"],["它不代表","不代表第四次、第五次碰到该斜线还不会跌破。"],["常见误区","在图上画一条陡峭得像80度悬崖的短期趋势线，一旦价格正常横盘歇两天自然穿过斜线，就惊慌失措地喊“大趋势反转崩盘了”，不知道过陡的斜率本来就无法持久，跌破陡线往往只是换成更平缓的上涨斜率。"]]},"t-113":{"title":"蜡烛图形态","line":"蜡烛图形态通过单根或两三根K线的开盘、最高、最低、收盘关系，帮你回答“这一时段谁掌控了收盘、盘中谁曾冲锋但被推回”。","points":[["看到什么","连跌到支撑带后，收出实体很小、下影线很长的K线：说明盘中空头虽一度砸深，但收盘前买盘把绝大部分失地收了回来。"],["它不代表","不代表单凭这一根K线已确认反转，仍需看下一根能否继续收高。"],["常见误区","在K线还没收盘时看到长下影线就急忙喊锤子线抄底，结果收盘前最后几分钟大跌把下影线全部填成大阴线。"]]},"t-114":{"title":"经典图表形态","line":"经典图表形态把几十根K线连成的轮廓归类为双顶底、头肩、三角形或旗形，帮你回答“多空在较长时间里怎样拉锯过渡，哪条边界被突破才算打破僵局”。","points":[["看到什么","两次冲到120元回落，随后放量收盘跌破中间低点110元颈线：说明二次冲高未创新高，且跌破110元使高低点下移，双顶结构按规则确认。"],["它不代表","不代表会跌满1倍高度，跌破后仍可能拉回110元上方形成假突破。"],["常见误区","在价格第二次刚摸到前高120元时，就迫不及待地重仓做空赌双顶，完全忘了在上升趋势里测试前高后直接向上突破才是家常便饭。"]]},"t-115":{"title":"价格行为（裸K）","line":"价格行为（裸K）直接通过K线波段的高低点排列、推进与回调的速度对比及关键位反应，帮你回答“市场是在上台阶、下台阶还是原地重叠拉锯”。","points":[["看到什么","高点抬高（100→106→112）、低点抬高（96→102→107），推进阳线饱满、回调K线细小：说明买方每次推进距离大于回调距离，上行台阶结构清晰。"],["它不代表","不代表在112元追高无风险，若跌破最新低点107元则上行节奏受损。"],["常见误区","以为拿掉指标就是“裸K高手”，结果没有任何客观的波段高低点规则，看一根大阳线就觉得主力要拉升、看一根大阴线就觉得要崩盘，沦为纯靠情绪追涨杀跌。"]]},"t-116":{"title":"道氏理论","line":"道氏理论把波动划分为主要趋势（潮汐）、次级折返（波浪）和日常小波动（涟漪），并看相关指数是否相互印证，帮你回答“眼前的下跌是大趋势反转，还是上涨中途的正常回撤”。","points":[["看到什么","大级别高低点持续抬升，中途回吐前段涨幅约一半后企稳再创新高：说明那波下跌只是主要上升趋势里的次级折返，主趋势假设继续保持。"],["它不代表","不代表每次跌50%都只是回调，若反弹不创新高且再破前低则主趋势存疑。"],["常见误区","指望用道氏理论买在最低点、卖在最高点——由于道氏理论必须等“反弹创出更低高点、随后再跌破前一个回调低点”才确认趋势反转，它天生是一套右侧滞后确认系统，往往会放弃头尾大约二三成的鱼头鱼尾空间。"]]},"t-117":{"title":"艾略特波浪理论","line":"艾略特波浪理论把顺势推进拆为5浪（1、3、5推进，2、4回调），把逆势修正拆为3浪（A、B、C），帮你回答“若当前符合标准波浪模型，哪个价位被破会直接证伪当前数浪假设”。","points":[["看到什么","假定第1浪从100涨到110，第2浪在103止跌并向上突破110元：说明回调未破第1浪起点100元（守住规则一），突破110元进入疑似第3浪推进。"],["它不代表","不代表这是唯一数法，它也可能只是ABC反弹里的C浪。"],["常见误区","千人千浪、事后诸葛亮——在实时行情里一旦价格跌破了第1浪起点或重叠了第1浪高点，不是按规则承认数浪错误并离场，而是顺手把鼠标一拖改成“复合调整浪WXYXZ”继续死扛。"]]},"t-118":{"title":"威科夫方法","line":"威科夫方法把横盘区间的价格高低与成交量变化放在一起对比，帮你回答“这段箱体横盘里，是下方抛压在枯竭，还是上方买盘在力竭”。","points":[["看到什么","二次、三次试探箱体下沿时，K线变短且成交量比初次大跌明显萎缩：说明同样来到低位，愿意低价抛售的卖盘比最初已显著减少。"],["它不代表","缩量不代表次日就拉升，仍需等待向上突破并回踩守住。"],["常见误区","死背教材上PS、SC、AR、ST、Spring、SOS、LPS十几个缩写字母，看到任何一段横盘都强行按顺序往里套，忘了真实市场可以没有Spring就直接突破，也可以走出三个假Spring后直接向下崩盘。"]]},"t-119":{"title":"谐波形态","line":"谐波形态用斐波那契比例逐段核对五点四腿（X-A-B-C-D）折线的长度关系，帮你回答“当前四段波段比例是否符合某种几何模型（如Gartley），以及潜在观察区（PRZ）落在哪”。","points":[["看到什么","AB回撤约0.618、BC在0.382-0.886之间，D点落在XA的0.786附近企稳：说明四段尺寸符合标准Gartley比例定义，价格在PRZ观察带内出现停顿。"],["它不代表","符合比例只说明图形合格，不代表D点必反转，PRZ同样可能被击穿。"],["常见误区","肉眼看到图上有个W形或M形的四段折线，连斐波那契尺子都没量，就大喊“出现蝴蝶形态了”冲进去交易。"]]},"t-120":{"title":"市场结构分析","line":"市场结构分析通过标记同周期连续的波段高点（HH/LH）与低点（HL/LL），帮你回答“当前趋势阶梯是在顺延（BOS），还是最新一级台阶已被反向击穿”。","points":[["看到什么","从更高低点（HL）起跳，K线收盘站上前一个波段高点（HH）上方：说明买方完成新一级向上台阶延伸，上行排列保持。"],["它不代表","不代表突破追高不会遇到回调，突破后常伴随回吐测试。"],["常见误区","看盘时没有固定周期概念，拿日线图的高点、1小时图的低点和5分钟图的小毛刺混在一起标HH和LL，结果自己把自己绕晕。"]]},"t-121":{"title":"江恩理论","line":"江恩工具（如江恩角度线Gann Fan）把“价格变动”与“经过的K线根数”绑定成固定比例斜线，帮你回答“若按每1根K线对应固定价格单位（1×1）作基准速度，当前走势是快于还是慢于该速度”。","points":[["看到什么","固定比例下，价格持续运行在1×1线上方，甚至沿2×1线推进：说明近期每根K线的平均上涨速度超过了设定的1×1基准速度。"],["它不代表","不代表1×1线有神秘护盘力量，改比例尺线的位置就会变。"],["常见误区","在没有锁定图表横纵坐标比例的情况下，看屏幕上某条线正好呈45度角就以为画出了正宗江恩1×1线——其实只要轻轻滚一下鼠标滚轮缩放屏幕，那条线和K线的关系就会面目全非。"]]},"t-122":{"title":"缠论","line":"缠论通过递进的几何合并规则，帮你回答“合并相邻重叠毛刺后，走势在同级别下如何围绕重叠中枢震荡或离开”。","points":[["看到什么","连续三笔在102到106元之间来回重叠，形成明确上下沿（ZG与ZD）的中枢框：说明走势在该价格带形成多笔反复拉锯的重叠区，暂时围绕该中枢震荡。"],["它不代表","不代表随便画一个横盘框就符合缠论中枢的严格笔段定义。"],["常见误区","在网上随便装两三个自动画笔、画中枢的指标插件，没发现每个插件作者写的包含处理、新老笔和线段特征序列源码规则都不一样，换个插件中枢就换个位置。"]]},"t-123":{"title":"SMC 智能资金概念","line":"SMC把前高前低、结构突破（BOS/CHOCH）及快速推进前的反向K线串成看图流程，帮你回答“价格刺穿前高前低后是否转向，以及回踩哪片起始区值得观察”。","points":[["看到什么","向上突破前高完成BOS，随后回落到起涨前阴线（OB框）内止跌收阳：说明回到突破起点区域时再次遇到买盘承接，结构防守边界紧凑。"],["它不代表","不能证明那个框里躺着某家银行未成交完的限价买单。"],["常见误区","深信“订单块里通常有银行机构没成交完的巨额限价单、机构为了解套通常会把价格拉回来”的故事，结果在价格直接大阴线击穿OB框时死扛不止损。"]]},"t-124":{"title":"ICT 交易方法","line":"ICT交易方法把纽约交易时段（Killzones）、前日高低点以及三根K线快速推进留下的“公允价值缺口（FVG）”组合成观察流程，帮你回答“在活跃时段内，价格是否在扫过前期高低点后走出带FVG的快速转向”。","points":[["看到什么","观察时段内先刺破前低（PDL），随后快速拉升并留下清晰看涨FVG：说明低点下方卖压被承接后买方快速推升，使第1与第3根影线未发生重叠。"],["它不代表","不代表价格必回头踩FVG，强单边行情可能一路涨走不回头。"],["常见误区","误以为名字叫“公允价值缺口（Fair Value Gap）”就代表那段价格里一笔成交都没有、像磁铁一样100%必须回头补上——其实中间第2根K线实体每一格都有真实成交，强趋势里留下的FVG可以好几个月都不回头补。"]]},"t-125":{"title":"订单流分析","line":"订单流分析把“已撮合成交的逐笔买卖单（Tape）”与“挂在盘口等待的限价单（DOM）”拆开对照，帮你回答“关键位上的挂单是真的被吃掉了，还是在成交前撤单跑了”。","points":[["看到什么","卖一100元挂大卖单，成交流跳出大量主动买单成交，但价格涨不过100元（吸收）：说明虽有很多主动买盘上冲，但100元处不断有被动限价卖单接住消化了买盘。"],["它不代表","不代表100元永远冲不过，一旦挂单被吃光反而会快速上跳。"],["常见误区","看到买一或买二档位挂着几千手巨额买单墙，就觉得“下面有大主力托底稳如泰山”立刻跟着买进，不知道大资金撤掉一笔未成交的限价挂单只需要几毫秒且不花一分钱手续费。"]]},"t-126":{"title":"拍卖市场理论","line":"拍卖市场理论把价格波动看作寻找“买卖双方都愿大量交手的价格区”的双向拍卖，帮你回答“当前价格是在旧价值区里被接受，还是已拒绝旧区、向外寻找新平衡”。","points":[["看到什么","开盘后一直在昨天VAH与VAL之间折返，成交和时间堆积在中间：说明买卖双方今天仍认可昨天的价值区间，处于平衡拍卖状态。"],["它不代表","平衡不会永远维持，一旦打破边界并获得接受就会转入失衡单边。"],["常见误区","看到“价值区（Value Area）”和“公允价值（Fair Value）”这两个词，就以为这是华尔街分析师按市盈率算出来的公司基本面估值，觉得跌破VAL就是股票便宜被低估了去长线死扛——其实它只是统计过去一天70%交易发生在哪的纯价格分布。"]]},"t-127":{"title":"供需区分析","line":"供需区分析把过去曾“短暂停顿后突然快速拉升或急跌”的起点K线框出来，帮你回答“历史失衡起跳台在哪个价格范围，以及首次回探时是否还有反应”。","points":[["看到什么","两根小K线窄幅整理后，连续大阳线拉出数倍于整理区宽度的涨幅：说明当时在该窄幅带买盘显著压倒卖盘，形成清晰的候选需求区。"],["它不代表","不能证明那个价格带现在还躺着未成交的机构限价买单。"],["常见误区","没有“快速有力离开”的筛选门槛，把图上所有普通的小横盘、小拐点全画成长方形框，导致屏幕上从100元到120元铺满了十几个框，价格走到哪都能马后炮说“踩中了我的供需区”。"]]},"t-128":{"title":"Trend Bars & Doji 趋势K与十字星","line":"趋势K是实体占整根波幅大部分、收盘靠近波幅一端的K线；十字星是开盘价与收盘价非常接近、实体很小的K线，本课以实体小于整根波幅的十分之一作为十字星的参考口径。","points":[["先做什么","先看实体占整根波幅的比例，再看收盘停在上端、下端还是中间。"],["打个比方","看一个人是迈大步往前走，还是在原地左右试探后又站回原处。"],["常见误区","把十字星直接当成反转信号是常见误解，它只表示这一根里多空暂时均衡，方向要看位置和后续收盘。"]]},"t-129":{"title":"Inside & Outside Bars 内包线与外包线","line":"内包线是当根最高价低于前一根最高价、且最低价高于前一根最低价的K线；外包线是当根最高价高于前一根最高价、且最低价低于前一根最低价的K线。","points":[["先做什么","打开数据窗口，逐根比对相邻两根的最高价和最低价，不要只凭眼睛估。"],["打个比方","看一根小棍子是不是完全装进了上一根的盒子，还是两头都伸出了盒子。"],["常见误区","把内包线当成孕线是常见混淆，孕线比的是实体，内包线比的是整根高低点，影线也算在里面。"]]},"t-130":{"title":"Pin Bars 长影线反转K","line":"Pin Bar 是单根K线：主影线长度大于实体长度的两倍，实体靠近波幅的一端，反向影线很短或没有；看涨 Pin Bar 是长下影线加靠近上端的实体，看跌 Pin Bar 是长上影线加靠近下端的实体。","points":[["先做什么","先量三段：主影线、实体、反向影线，不要只看影线很长。"],["打个比方","像把手伸向很远的东西又缩回来，伸得远不代表拿到了那样东西。"],["常见误区","把每一根长影线都当 Pin Bar 是常见误解，影线长、实体小、收盘位置和出现位置要同时满足，区间中间的长影线参考价值较低。"]]},"t-131":{"title":"Breakouts & Failed Breakouts 突破与假突破","line":"突破：一根K线的收盘价越过此前区间的最高价（或最低价）。","points":[["先做什么","先用区间里各根的最高价、最低价画出上下边界。"],["打个比方","像推门出去，脚刚迈出又缩回屋里，门外没人接应。"],["常见误区","把盘中刺破边界当成突破、立刻追进去是最常见的错误。"]]},"t-132":{"title":"Pullbacks & Second Entries 回调与二次入场","line":"在上涨趋势的回调里，第一根最高价高于前一根最高价的K线叫 H1（High 1）；之后回调继续创出新低，再出现一根最高价高于前一根最高价的K线叫 H2，也就是“二次入场”的信号K位置。","points":[["先做什么","先确认大方向是上涨：高点、低点在抬高。"],["打个比方","像下楼梯时停了两次脚，第二次停住往上看，比第一次更像要折返。"],["常见误区","常见数错是把回调中任何一根阳线都当成 H1。"]]},"t-133":{"title":"Wedges & Three Pushes 楔形与三推","line":"三推：同一方向连续出现三个摆动高点（或低点），每一个都高于（低于）前一个，但每次推进的幅度逐次缩小。","points":[["先做什么","在一段趋势里找三个同方向的摆动高点（或低点）。"],["打个比方","像跳台阶，第一次跳得高，第二次低一点，第三次只勉强够到。"],["常见误区","很多人数到第三个高点就认定会反转。"]]},"t-134":{"title":"Trading Ranges 交易区间","line":"交易区间：一段K线中，价格反复在大致固定的上下边界之间来回，没有持续创出更高的高点和更高的低点（或更低的高点和更低的低点）。","points":[["先做什么","找出价格多次掉头的上沿和下沿，各至少触及两次。"],["打个比方","像在走廊里来回踱步，两头的墙挡着，直到有一天推开了一扇门。"],["常见误区","新手常在区间中部追涨杀跌。"]]},"t-135":{"title":"Measured Moves 等距运动","line":"等距运动（Measured Move）：把第一段走势（A 到 B）的价格幅度，从回调结束点 C 开始向同一方向复制一次，得到参考价 D = C + (B − A)（上涨）或 D = C − (A − B)（下跌）。","points":[["先做什么","标出第一段的起点 A 和终点 B，量出 B − A。"],["打个比方","像用第一步的步长，估计第二步大概落在哪里。"],["常见误区","把 D 当成必到的目标价是最常见的误解。"]]},"t-136":{"title":"Channel Lines & Overshoots 通道线与超越","line":"在上升通道里，通道线是平行于趋势线、画在高点一侧的线。","points":[["先做什么","用两个以上的低点画趋势线，再过一个高点画平行的通道线。"],["打个比方","像车冲出弯道外侧：要么油门更大真的冲出去，要么被护栏弹回来。"],["常见误区","把每一次冲出通道线都当成加速追进去，是常见错误。"]]},"t-137":{"title":"Climaxes & Exhaustion 高潮与衰竭","line":"高潮（climax）：一段趋势末端连续出现异常大的同向K线，波幅明显大于此前平均水平（本课取前 20 根平均波幅的 2 倍以上），通常伴随放量。","points":[["先做什么","算出前 20 根左右的平均波幅，作为“正常大小”。"],["打个比方","像马拉松最后的冲刺，冲过之后多半要停下来喘气。"],["常见误区","看到一根大阳线就喊见顶是常见误判。"]]},"t-138":{"title":"Gaps 缺口","line":"向上缺口：当根最低价高于前一根最高价，两根之间留下没有成交的价格区间；向下缺口反之。","points":[["先做什么","比较当根最低价与前一根最高价（向下缺口反过来比）。"],["打个比方","像楼梯少了一级，脚直接跨到了上一层。"],["常见误区","“缺口必补”是常见说法，但并不成立：很多突破缺口长期不回补。"]]},"t-139":{"title":"Multi-timeframe Analysis 多周期分析","line":"多周期分析：用较大周期判断背景（趋势方向和关键价位），再用较小周期观察价格在这些位置的具体表现。","points":[["先做什么","先选一组比例约 4–6 倍的周期，例如 4 小时和 1 小时。"],["打个比方","像先看地图确定往哪个城市走，再看街道图决定从哪个路口拐。"],["常见误区","不停切换周期、找一个支持自己想法的图，是最常见的错误。"]]},"t-140":{"title":"Engulfing Patterns 吞没形态","line":"看涨吞没：前一根是阴线，当根是阳线，当根实体完全覆盖前一根实体（当根开盘不高于前一根收盘、收盘高于前一根开盘）。","points":[["先做什么","先看位置：看涨吞没出现在下跌之后才有参考意义。"],["打个比方","像拔河时对方刚往前拉了一步，你一口气不但拉回来，还多拉了一截。"],["常见误区","在横盘中间看到吞没就当成反转信号，是最常见的误用。"]]},"t-141":{"title":"Hammer & Hanging Man 锤子线与上吊线","line":"形状：下影线长度至少是实体的 2 倍，上影线很短（不超过实体），实体位于整根波幅的上部。","points":[["先做什么","量出实体、下影线、上影线，核对比例。"],["打个比方","同一把伞，晴天叫遮阳伞，雨天叫雨伞，看的是用在什么天气。"],["常见误区","只认形状、不看位置，把上涨途中的同形K线也当成看涨的锤子线，是最常见的混淆。"]]},"t-142":{"title":"Shooting Star & Inverted Hammer 射击之星与倒锤子","line":"形状：上影线长度至少是实体的 2 倍，下影线很短（不超过实体），实体位于整根波幅的下部。","points":[["先做什么","量出实体、上影线和下影线，核对比例。"],["打个比方","像向上扔球被风吹回来：在山顶说明风大，在山谷说明有人试着往上扔。"],["常见误区","把上涨途中每一根长上影都当成见顶信号，是常见误判。"]]},"t-143":{"title":"The Doji Family 十字星家族","line":"十字星：实体小于整根波幅的 10%。","points":[["先做什么","先算实体占波幅的比例，确认小于 10%。"],["打个比方","像拔河拉了半天，绳子又回到原点；谁赢还要看下一轮。"],["常见误区","把墓碑十字直接当卖出信号、蜻蜓十字直接当买入信号，是最常见的误用。"]]},"t-144":{"title":"Morning & Evening Stars 早晨之星与黄昏之星","line":"早晨之星：第一根是长阴线；第二根是实体小于第一根实体三分之一的“星线”；第三根是阳线，收盘高于第一根实体的中点。","points":[["先做什么","找一根趋势方向的长K线，记下它的实体中点。"],["打个比方","像天黑到最暗的时候停顿一下，然后天开始亮了。"],["常见误区","只要看到“大阴、小K、大阳”就认定早晨之星，却不核对第三根是否收过第一根实体中点，是常见的放宽错误。"]]},"t-145":{"title":"Three White Soldiers & Three Black Crows 三白兵与三乌鸦","line":"三白兵：连续三根阳线，每根收盘都高于前一根收盘，每根上影线都不超过本根波幅的 30%（收在高位附近）。","points":[["先做什么","找连续三根同色K线，核对收盘逐根抬高（或降低）。"],["打个比方","像连走三级台阶都踩得很稳，但连续走快了也需要歇一歇。"],["常见误区","在已经大涨很久之后看到三白兵就追高，是常见错误。"]]},"t-146":{"title":"Harami 孕线","line":"孕线：后一根K线的实体完全落在前一根实体的范围内（与边界相等也算），后一根实体小于前一根实体的一半，两根颜色通常相反。","points":[["先做什么","找一根实体较大的K线，记下它的实体上下沿。"],["打个比方","像一个大口袋里装着一个小盒子，比的是盒身，不管盒子上的提手。"],["常见误区","把孕线和内包线混为一谈是最常见的错误：孕线比实体，内包线比整根高低点。"]]},"t-147":{"title":"Dark Cloud Cover & Piercing Pattern 乌云盖顶与刺透","line":"乌云盖顶：前一根是长阳线；后一根冲高越过前一根最高价后回落，收成阴线，收盘低于前一根实体的中点、但高于前一根开盘价。","points":[["先做什么","找一根长阳线，算出实体中点。"],["打个比方","像一个人刚登上新高度，脚下一滑退回半山腰以下。"],["常见误区","把收盘只回落到实体中点以上的阴线也叫乌云盖顶，是常见的放宽。"]]},"t-148":{"title":"Head & Shoulders 头肩顶与头肩底","line":"头肩顶：三个摆动高点中，中间的“头”高于左右两个“肩”；两肩之间的两个低点连成颈线。","points":[["先做什么","找出三个高点，确认中间最高、两侧较低。"],["打个比方","像爬山时第三次登高明显没前一次高，体力在下降。"],["常见误区","右肩还没走完就认定头肩顶，或把参考幅度当成必到目标，是两个最常见的错误。"]]},"t-149":{"title":"Double Tops & Bottoms 双顶与双底","line":"双顶：两个相近的摆动高点（第二个可以略高或略低，本课取相差不超过 1%），中间夹一个摆动低点；收盘跌破中间低点才算形态完成。","points":[["先做什么","找两个相近的高点，核对差距（本课取不超过 1%）。"],["打个比方","像两次推门都没推开，但门没锁死之前，第三次也许就开了。"],["常见误区","第二个高点刚出现就当双顶卖出，是最常见的提前判断。"]]},"t-150":{"title":"Triangles 三角形","line":"三角形：价格的摆动高点和摆动低点各连成一条线，两线向右收敛。","points":[["先做什么","至少找两个摆动高点和两个摆动低点，分别连线。"],["打个比方","像两面墙慢慢合拢，人迟早要从某一边出去，但先往哪边走说不准。"],["常见误区","认定上升三角形一定向上突破，是常见的过度简化。"]]},"t-151":{"title":"Flags & Pennants 旗形与三角旗","line":"旗形：先有一段急速的“旗杆”（几根大K线），随后价格在一个与旗杆方向相反、小幅倾斜的平行通道里整理（旗面），整理回撤不超过旗杆的一半；三角旗的旗面是小型收敛三角形。","points":[["先做什么","先找旗杆：几根方向一致的大K线。"],["打个比方","像短跑冲刺后小跑两步调整呼吸，再继续往前跑。"],["常见误区","把任何一段回调都当成旗形，而不看旗杆是否足够急、回撤是否太深，是常见错误。"]]},"t-152":{"title":"Rectangles 矩形整理","line":"矩形：价格在两条大致水平的线之间来回，上沿至少触及两次、下沿至少触及两次，形成一个箱体；收盘越过上沿或下沿才算突破。","points":[["先做什么","画出上下两条水平线，各至少触及两次。"],["打个比方","像在两层楼之间上下楼梯，直到某一天走出了楼。"],["常见误区","以为矩形之后一定沿原趋势方向突破，是常见误解。"]]},"t-153":{"title":"Rising & Falling Wedges 楔形形态","line":"上升楔形：摆动高点和摆动低点都在抬高，但低点抬高得更快，两条连线向上收敛；收盘跌破下边线为向下突破。","points":[["先做什么","连接至少两个高点和两个低点，确认两条线方向相同并收敛。"],["打个比方","像在越来越窄的上坡路上骑车，越骑越费劲。"],["常见误区","把所有向上收敛的走势都叫上升楔形，而不比较两条线的斜率，是常见错误。"]]},"t-154":{"title":"Cup and Handle 杯柄形态","line":"杯柄：价格从一个高点（杯沿）回落，形成圆弧形的底部（杯身，而不是尖底），再回到接近原杯沿的位置；之后小幅回撤形成“柄”，柄的回撤幅度小于杯身深度的一半。","points":[["先做什么","找出杯沿与杯底，确认底部是圆弧而不是尖底。"],["打个比方","像一只茶杯的侧影：圆底、杯沿，再加一个小把手。"],["常见误区","把 V 形的急跌急涨也画成杯柄，或忽略柄的回撤过深，都会让形态失去原本的含义。"]]},"t-155":{"title":"Rounding Bottoms & V Reversals 圆弧底与 V 形反转","line":"圆弧底：下跌逐渐放缓、在低位横向停留较长时间，再逐渐回升，形成平缓的 U 形；V 形反转：急跌之后几乎没有停留就急涨，本课以“8 根K线内下跌超过 4%，随后 8 根K线内收复跌幅的 80% 以上”作为识别口径。","points":[["先做什么","先看下跌的速度：逐渐放缓还是急跌。"],["打个比方","圆弧底像船慢慢掉头，V 形反转像皮球砸地马上弹起。"],["常见误区","在急跌途中“猜 V 形反转”去抄底是最常见的错误。"]]},"t-156":{"title":"Divergence 背离","line":"常规顶背离：价格的第二个摆动高点高于第一个，同一时刻对应的指标高点却低于第一个；常规底背离反之。","points":[["先做什么","先在价格上找两个摆动高点（或低点）。"],["打个比方","像车速表显示在减速，车却还在往前开，迟早要看会不会停。"],["常见误区","用指标的另一个高点去配价格高点，或把背离直接当成卖点，是最常见的两个错误。"]]},"t-157":{"title":"Volume and Price 量价关系","line":"量价关系把每段走势分成四种组合：价涨量增、价涨量缩、价跌量增、价跌量缩。","points":[["先做什么","把走势分段：一段上涨、一段回调或一段下跌。"],["打个比方","像看一场游行：队伍往前走时人越来越多，还是越走人越少。"],["常见误区","把“放量上涨一定是好事、缩量一定是坏事”当成规则是常见误解。"]]},"t-158":{"title":"TD Sequential 九转序列","line":"TD Sequential 分两步。","points":[["先做什么","从一次价格翻转开始：前一根不满足条件，当根开始满足。"],["打个比方","像数一个人连续跑了几圈，圈数多了可能要累，但不保证马上停下。"],["常见误区","“九转到 9 就反转”是最常见的误用。"]]},"t-159":{"title":"Heikin Ashi 平均K线","line":"Heikin Ashi 用原始K线重新计算：HA 收盘 =（开 + 高 + 低 + 收）÷ 4；HA 开盘 =（前一根 HA 开盘 + 前一根 HA 收盘）÷ 2；HA 最高 = 原最高、HA 开盘、HA 收盘中的最大值；HA 最低取最小值。","points":[["先做什么","在图表类型里切换到 Heikin Ashi。"],["打个比方","像把一段颠簸的路用平均速度画成一条平滑的线，好看了，但不是每一刻的真实车速。"],["常见误区","把 HA 图上的收盘价当成真实成交价来定止损或做回测，是最常见、也最危险的错误。"]]},"t-160":{"title":"Renko Charts 砖形图","line":"Renko 砖形图只在价格走完一个固定幅度（砖块大小）时画一块砖：收盘比上一块砖的顶部高出至少一块砖，就向上画砖；比底部低出至少两块砖（反向需要两块）才向下画砖。","points":[["先做什么","选定砖块大小（固定值或按 ATR 计算），并记下来。"],["打个比方","像只在爬过一整级台阶时才记一笔，在台阶上来回走动不算。"],["常见误区","忽略砖块大小的选择，或以为砖块之间的距离代表时间，是最常见的误解。"]]},"t-161":{"title":"Point & Figure Charts 点数图","line":"点数图用 X 列记录上涨、O 列记录下跌，每个格子代表一个固定价格幅度（格值）。","points":[["先做什么","选定格值和反转格数（常用 3 格），并记下来。"],["打个比方","像在方格纸上记账：只有金额变化够一格才写一笔，时间不记。"],["常见误区","改变格值或反转格数却仍用同样的结论，是常见错误。"]]},"t-162":{"title":"Cost Distribution (Chip Distribution) 筹码分布","line":"筹码分布（成本分布）是一种估算：假设每天成交的部分按换手率“替换”旧持仓，把成交量分配到当天的价格区间，逐日累积并衰减旧筹码，得到“当前持有者的成本大致分布在哪些价位”。","points":[["先做什么","先确认使用的是成本分布还是成交量分布，以及平台的计算假设。"],["打个比方","像根据每天进出电影院的人数，估算现在还坐在里面的人是几点进场的。"],["常见误区","把筹码分布当成真实的持仓数据，认为“主力成本就在这里”，是最常见的误解。"]]},"t-163":{"title":"Basis & Premium 基差与溢价","line":"本课按加密市场常见用法定义：基差 = 合约价格 − 现货价格（也有教材按现货 − 合约计算，看平台口径）；溢价率 = 基差 ÷ 现货价格。","points":[["先做什么","确认比较的是同一标的、同一时刻的合约价与现货价。"],["打个比方","像预订明年的机票和今天买机票的价差，差价反映的是大家对未来的需求和资金成本。"],["常见误区","把正溢价直接当成“看涨信号”是常见误解。"]]},"t-164":{"title":"Order Book Depth & Liquidity Heatmaps 盘口深度与流动性热力图","line":"盘口深度（订单簿）列出各价位上尚未成交的买单和卖单数量；流动性热力图把这些挂单随时间画成颜色，颜色越亮代表该价位挂单越多。","points":[["先做什么","确认看的是哪个交易所、哪个交易对的盘口，单个交易所只代表局部。"],["打个比方","像商店门口贴的“大量收购”告示，随时可以撕掉，告示不等于交易已经发生。"],["常见误区","把热力图上的亮带当成必然的支撑或阻力，是最常见的误解。"]]},"t-165":{"title":"Darvas Box 箱体理论","line":"达瓦斯箱体：价格创出新高后，若接下来连续 3 根K线都没有超过这个高点，该高点就是箱顶；箱顶确认后，若随后出现一个低点且接下来连续 3 根都没有跌破它，该低点就是箱底。","points":[["先做什么","在上涨中找新高，看接下来 3 根是否都没超过它，确定箱顶。"],["打个比方","像楼梯的每一级平台：走到平台上歇一下，再往上走一级。"],["常见误区","不按规则随手画框，或在箱顶还没确认时就“预判突破”，会让箱体失去意义。"]]},"t-166":{"title":"Turtle Trading 海龟交易法则","line":"海龟交易法则是一套规则化的趋势跟踪系统。","points":[["先做什么","用唐奇安通道标出过去 20（或 55）根的最高价和 10（或 20）根的最低价。"],["打个比方","像一份写死的菜谱：火候、用量、时间都规定好，不凭感觉调。"],["常见误区","只学突破入场，不按 ATR 控制仓位、也不按规则离场，是最常见的走样。"]]},"t-167":{"title":"Triple Screen 三重滤网","line":"三重滤网用三个相差约 5 倍的周期分工：第一层（长周期，如周线）用趋势指标确定方向，只做该方向；第二层（中周期，如日线）用振荡指标找逆向回调，例如上升趋势中振荡指标进入超卖；第三层（短周期或盘中）用价格本身决定入场，例如在前一根高点上方设置买入止损单。","points":[["先做什么","在长周期用趋势指标（如 MACD 柱状线斜率）确定方向。"],["打个比方","像过三道门禁：先确认能进大楼，再确认能上楼层，最后才刷卡开房门。"],["常见误区","三层不按顺序用，或在长周期方向相反时仍按中周期信号操作，会让这套系统失去“过滤”的作用。"]]},"t-168":{"title":"Moving Average Alignment 均线多空排列","line":"均线多头排列：短期均线在中期均线之上、中期在长期之上（如 MA5 > MA10 > MA20），且三条均线都在上升；空头排列反之。","points":[["先做什么","在图上加三条周期不同的均线，例如 5、10、20。"],["打个比方","像排队爬坡的三个人，跑得快的在前面，大家都在往上走。"],["常见误区","看到多头排列就认为会一直涨、在排列形成很久后追高，是常见误解。"]]},"t-169":{"title":"Trend vs Range 趋势与震荡的判断","line":"趋势：在一段K线里，摆动高点和低点同向推进（上涨中更高的高点与更高的低点），收盘大多在一侧，均线方向明确。","points":[["先做什么","标出最近的几个摆动高点和低点，看是否同向推进。"],["打个比方","像判断今天是顺风还是来回乱吹的风，选的帆不一样。"],["常见误区","在震荡里用均线交叉追涨杀跌，或在强趋势里用超买超卖逆势操作，是最常见的“工具用错场合”。"]]},"t-170":{"title":"Cutting Losses 止损与认错","line":"止损：在开仓前写下“这笔交易被证明错了”的条件（失效点，可以是一个价格，也可以是一个收盘条件），条件出现就按计划平仓，不因为不想承认亏损而推迟。","points":[["先做什么","开仓前写下失效条件：哪个价位或哪种收盘说明判断错了。"],["打个比方","像开车前先确定刹车在哪里：不是因为想撞车，而是为了真出状况时能停下来。"],["常见误区","把止损越挪越远、或者因为“已经亏了这么多”而不卖，是小亏变大亏的主要原因。"]]},"t-171":{"title":"Averaging Down vs Adding to Winners 补仓与加仓","line":"补仓（摊低成本）：持仓亏损时以更低的价格再买入，使平均成本下降。","points":[["先做什么","先写下这笔交易的失效价，补仓或加仓前都要重新算总风险。"],["打个比方","补仓像在漏水的船上再多装一点货，希望船早点靠岸；浮盈加仓像顺风时多扬一面帆。"],["常见误区","一路补仓把平均成本拉低，却让总风险成倍放大。"]]},"t-172":{"title":"Expectancy & Win Rate 期望值与胜率","line":"期望值（每笔平均盈亏）= 胜率 × 平均盈利 −（1 − 胜率）× 平均亏损，其中平均亏损取正数。","points":[["先做什么","记录至少几十笔交易，分别算出胜率、平均盈利和平均亏损（含手续费与滑点）。"],["打个比方","像开店：每天成交的单数多不多不是重点，重点是一个月下来收入减成本是多少。"],["常见误区","只追求高胜率而忽略亏损大小。"]]},"t-173":{"title":"Trading Psychology & Biases 交易心理与常见偏差","line":"交易中的常见认知偏差包括：赌徒谬误（以为连涨之后“该跌了”、连亏之后“该赚了”）、损失厌恶（同样金额，亏损带来的痛苦大于盈利带来的快乐）、处置效应（太早卖出盈利单、太久持有亏损单）、锚定（拿过去的价格判断现在贵或便宜）和事后诸葛亮（把事后的解释当成事前可以预见）。","points":[["先做什么","交易前写下入场理由、失效条件和目标，避免事后找理由。"],["打个比方","像减肥时不在家里囤零食：不是相信自己没有食欲，而是承认会有，提前把环境安排好。"],["常见误区","以为“知道这些偏差”就能避免。"]]},"t-174":{"title":"Liquidity & Market Impact 流动性与冲击成本","line":"流动性：在不明显改变价格的前提下买卖一定数量的能力，常用买卖价差、盘口挂单深度和成交量衡量。","points":[["先做什么","下单前看买卖价差和前几档挂单量，估算你的数量要吃掉几档。"],["打个比方","像在小菜市场一次买光所有西红柿：前几斤是原价，后面摊主就开始涨价了。"],["常见误区","只看K线和成交量就以为可以随时按图上的价格成交。"]]},"t-175":{"title":"What a Stock Is 股票是什么","line":"股票是公司所有权的一份凭证。","points":[["先做什么","先分清你买的是哪家公司、在哪个市场上市、股票代码是什么。"],["打个比方","像几个人合伙开一家面馆，每人按出资多少分利润；只是上市公司的“合伙人”有成千上万个，份额可以随时在市场上转让。"],["常见误区","把股价高低当成贵贱，例如觉得 2 元的股票比 200 元的“便宜”。"]]},"t-176":{"title":"Exchanges, Brokers & Trading Rules 交易所、券商与交易规则","line":"交易所是撮合买卖的场所（如纽约证券交易所、纳斯达克、上海与深圳证券交易所），普通投资者通过券商开户下单。","points":[["先做什么","确认要交易的市场：A 股、港股、美股还是加密资产，它们的交易时间不同。"],["打个比方","像在不同国家开车：都是开车，但靠左还是靠右、限速多少，各地规定不同。"],["常见误区","以为所有市场都能当天买卖、随时成交。"]]},"t-177":{"title":"Placing Orders: Market vs Limit 下单基础：市价单与限价单","line":"市价单：按当时能成交的最好价格立即成交，优先保证成交、不保证价格。","points":[["先做什么","先决定：更在乎一定成交，还是更在乎成交价格。"],["打个比方","市价单像在菜市场说“按你现在的价给我来一斤”；限价单像说“降到 8 块一斤我就买，否则先不买”。"],["常见误区","以为挂了限价单就一定能按那个价成交。"]]},"t-178":{"title":"Indexes & ETFs 指数与 ETF","line":"股票指数用一篮子股票的价格计算出一个数字，代表某个市场或板块的整体表现，例如标普 500、纳斯达克 100、沪深 300。","points":[["先做什么","先查指数包含哪些成分股、多少只、按什么方式加权。"],["打个比方","指数像班级的平均分，ETF 像把全班的作业打包成一份来买。"],["常见误区","以为指数涨了自己的股票也该涨。"]]},"t-179":{"title":"What Crypto Assets Are 加密资产是什么","line":"加密资产是记录在区块链上的数字资产。","points":[["先做什么","确认资产的名称、代码以及它运行在哪条区块链上（同名资产可能在多条链上存在）。"],["打个比方","区块链像一本大家各自保存副本的公共账本，谁想改一页旧账，都得同时改掉大多数人手里的副本。"],["常见误区","只看单价觉得“便宜”，例如认为 0.001 美元的代币比 1 美元的更有上涨空间。"]]},"t-180":{"title":"Wallets & Exchange Custody 钱包与交易所托管","line":"托管：资产放在交易所账户里，由交易所保管私钥，你用账号密码登录使用。","points":[["先做什么","决定哪些资产放交易所（准备交易的），哪些转到自己的钱包（长期持有的）。"],["打个比方","托管像把钱存进别人开的保险箱，钥匙在店家手里；自托管像把现金锁进自家保险柜，钥匙丢了没人能帮你开。"],["常见误区","把助记词截图存在手机相册或云盘。"]]},"t-181":{"title":"Stablecoins Basics 稳定币入门","line":"稳定币是目标价格锚定某种资产（最常见的是 1 美元）的加密代币。","points":[["先做什么","查清稳定币的类型和发行方：靠储备、超额抵押还是算法维持。"],["打个比方","像商场发行的储值卡，标明能当 100 元用，但它值不值 100 元，取决于商场还在不在、账上有没有钱。"],["常见误区","把稳定币当成没有风险的现金。"]]},"t-182":{"title":"Spot, Margin & Leveraged Contracts 现货、杠杆与合约","line":"现货：用全额资金买入资产本身，价格跌了只是浮亏，不会被强制卖出（借钱买入的除外）。","points":[["先做什么","先分清自己交易的是现货还是合约，看清下单页面上的杠杆倍数。"],["打个比方","现货像用自己的钱买房，跌价只是账面缩水；高杠杆像只付一成首付，价格跌一成，首付就没了。"],["常见误区","只看收益放大，不看亏损同样放大。"]]},"t-183":{"title":"Beginner Safety: Scams & Money Management 新手安全：骗局与资金管理","line":"常见骗局包括：承诺稳定高收益的投资项目或“带单”、冒充客服或熟人索要验证码与助记词、仿冒网站与应用（钓鱼）、由陌生人长期培养信任后引导投资的“杀猪盘”、以及拉高后抛售（拉盘砸盘）的喊单群。","points":[["先做什么","把“保本”“稳赚”“每天固定收益”“名额有限马上打款”当成危险信号。"],["打个比方","像出门旅行：先把护照和钱包看好，再去研究景点；钱包丢了，行程再好也走不下去。"],["常见误区","看到别人晒收益截图就跟着转账。"]]},"t-184":{"title":"Reading Financial Statements 读懂三张财报","line":"三张财报是基于会计准则编制的核心报告体系：利润表（净利润 = 营业收入 - 营业成本 - 期间费用 - 税费）反映特定期间的经营盈亏；资产负债表（资产 = 负债 + 所有者权益）反映特定时点的财务状况；现金流量表（期末现金 = 期初现金 + 经营/投资/筹资活动现金净流量）反映特定期间真实的现金流入与流出。","points":[["先做什么","在法定披露平台（SEC EDGAR、巨潮资讯网或披露易）检索目标公司最新的10-K/年报或10-Q/季报原文。"],["打个比方","利润表是成绩单，资产负债表是体检快照，现金流量表是体内流动的血液。"],["常见误区","误将账面净利润等同于公司可随时支配的银行存款，忽视客户欠款或存货积压可能导致的严重资金链断裂风险。"]]},"t-185":{"title":"Valuation Multiples: P/E, P/B, and P/S 估值指标：市盈率、市净率与市销率","line":"估值倍数是通过股价与特定财务基础指标对比衡量相对价格的指标体系。","points":[["先做什么","在行情软件或财报软件输入股票代码，调出P/E（TTM）、Forward P/E、P/B与P/S估值面板。"],["打个比方","估值倍数就像买房时的每平米单价，方便对比不同总价房产的相对要价。"],["常见误区","误将低市盈率直接等同于物美价廉，忽视企业可能因行业衰退、技术淘汰或巨额隐性负债而遭遇市场系统性折价。"]]},"t-186":{"title":"Earnings Season & Guidance 财报季与业绩预期","line":"财报季是上市公司集中披露季度或年度财务报告的周期；业绩预期是华尔街分析师对营收与每股收益形成的平均共识（Consensus Estimates）；业绩指引（Guidance）是公司管理层对未来财务表现的前瞻性官方预测。","points":[["先做什么","在财报日历（如Nasdaq Earnings Calendar或券商日历）确认目标公司的财报发布时间是盘前（BMO）还是盘后（AMC）。"],["打个比方","财报就像考试，市场预期考95分，即使考了90分在市场眼里依然不及格。"],["常见误区","以为当季净利润大幅增长就必然带动股价上涨，忽视管理层前瞻指引下调或利好已被提前消化带来的断崖式跳空风险。"]]},"t-187":{"title":"Dividends & Corporate Actions 除权除息与公司行动","line":"除权除息（Ex-Dividend / Ex-Rights）是上市公司在实施现金分红或送转股时，按法定规则从股票市场价格中扣除分红价值或稀释股本的交易制度。","points":[["先做什么","在上市公司公告中核实四个关键日期：预案公告日、股权登记日（Record Date）、除权除息日（Ex-Date）与派息日（Payable Date）。"],["打个比方","分红就像把钱从钱包左边夹层换到右边，左边变薄了但个人总资产并没有凭空增加。"],["常见误区","误以为除息日分红是天上掉馅饼的额外奖金，未意识到股价除权后总市值同步扣除，若陷入贴权行情反而会损失本金。"]]},"t-188":{"title":"IPOs & New Listings 新股申购与上市","line":"首次公开发行（IPO，Initial Public Offering）是私有企业首次向社会公众公开发售股票并在交易所挂牌交易的融资过程。","points":[["先做什么","在交易所披露平台查阅招股说明书（Prospectus / Form S-1），评估主营业务、募资投向与保荐机构声誉。"],["打个比方","IPO就像楼盘新开盘，发行价是指导价，能否赚钱看排队买家是否买单。"],["常见误区","以为新股申购就稳赚不赔，忽视全面注册制与海外成熟市场中破发属于常态化市场化现象。"]]},"t-189":{"title":"Options Basics 期权入门","line":"期权（Options）是赋予买方在约定到期日或之前以约定行权价（Strike Price）买入或卖出标的资产权利而非义务的标准化金融衍生合约。","points":[["先做什么","在期权T型报价表（Option Chain）中核对标的资产、行权价（Strike）、到期日（Expiration）与买卖价差。"],["打个比方","买期权就像买车险，买方支付保费获得保障，若平稳无事保费归零，出大事故则获得赔偿。"],["常见误区","以为买入期权看对方向就能赚钱，未意识到即使股票微涨，若未能跑赢时间价值衰减或隐含波动率暴跌（IV Crush），期权仍会亏损归零。"]]},"t-190":{"title":"Backtesting & Overfitting 回测与过拟合","line":"回测（Backtesting）是将明确的交易规则代入历史行情数据以模拟检验策略表现的方法；回测净收益 = 模拟总毛利 - 累计手续费 - 累计滑点损耗。","points":[["先做什么","将历史行情严格切分为两段：样本内数据（In-Sample）用于设计策略逻辑，样本外数据（Out-of-Sample）用于独立检验。"],["打个比方","过拟合就像背下去年考卷的答案顺序去参加今年高考，题型一变就会彻底考砸。"],["常见误区","在整段历史数据上反复修改参数直到资金曲线完美向上，却未留出独立的样本外数据做盲测，把拟合历史噪音当成了圣杯。"]]},"t-191":{"title":"Trading Plan & Journal 交易计划与交易日志","line":"交易计划（Trading Plan）是开仓前制定的书面行动契约，包含交易标的、触发条件、仓位上限（单笔可承受亏损金额 ÷ 每股止损空间）、失效止损位与止盈退出规则；交易日志（Trading Journal）是盘后客观记录每笔交易执行要素、偏差原因与情绪状态的统计档案。","points":[["先做什么","在开盘或下单前写下书面计划：明确买什么标的、满足什么客观条件入场、最多买多少股。"],["打个比方","交易计划像航班起飞前的飞行检查单，交易日志则是降落后的黑匣子飞行记录仪。"],["常见误区","把盘前模糊的“看涨感觉”当成交易计划，或者只在盈利时记账炫耀、亏损时拒绝复盘，导致同样的冲动错误反复发生。"]]},"t-192":{"title":"Seasonality & Calendar Effects 季节性与日历效应","line":"季节性与日历效应（Seasonality & Calendar Effects）是指金融资产收益率在特定月份、季度、星期或节假日前后呈现出历史统计均值偏离的日历异象（Calendar Anomalies）。","points":[["先做什么","明确日历效应背后的真实制度或经济驱动力（如年底税务亏损抛售Tax-loss Selling、季末基金粉饰报表Window Dressing或大宗商品季节性供需）。"],["打个比方","日历效应就像历史气象统计，立秋后平均气温会降，但某一年立秋当天仍可能酷热难耐。"],["常见误区","把长周期算出的微弱正平均收益率当成每年必然重演的铁律，忽视极端年份的单次黑天鹅足以吞噬多年累积的微弱均值优势。"]]},"t-193":{"title":"Margin Financing Balance 融资融券余额","line":"融资融券余额（Margin Financing and Securities Lending Balance）是市场上投资者向证券公司借入资金买入证券（融资）与借入证券卖出（融券）尚未偿还的累计存量总和。","points":[["先做什么","每个交易日前往上海证券交易所、深圳证券交易所融资融券专栏或中证金融官网，查看前一交易日的两融市场汇总与个股明细。"],["打个比方","两融余额就像牌桌上借筹码的总账单，筹码变多说明赌兴正浓，不代表接下来会赢。"],["常见误区","误把两融余额上升当成主力机构建仓的领先信号，实际上两融多为趋势跟随型散户与游资杠杆，往往滞后于行情甚至在顶部站岗。"]]},"t-194":{"title":"Dragon-Tiger List 龙虎榜","line":"龙虎榜（法定名称：证券交易公开信息）是沪深北证券交易所在每个交易日收盘后，对当日涨跌幅偏离值、振幅、换手率或连续三个交易日累计偏离值达到《交易规则》规定阈值的异动证券，依法公开披露其成交金额最大的前五家证券营业部或交易单元名称及买卖金额的制度。","points":[["先做什么","每个交易日收盘后（当晚），在沪深北交易所官网“交易公开信息”专栏查阅当日上榜证券及上榜原因。"],["打个比方","看龙虎榜跟单就像看着昨天的球赛集锦去买今天的球票，场上的胜负早已成为过去式。"],["常见误区","误以为榜上的营业部代表单一庄家账户，或以为看到“机构专用”买入就安全，忽视机构席位同样存在一日游短线操作甚至量化分仓。"]]},"t-195":{"title":"Limit-up Boards 涨停板与连板","line":"涨停板（Limit-Up）是证券交易所在单日竞价交易中规定的证券价格相对前一日收盘价的最大允许上涨幅度（见本站「交易所、券商与交易规则」一课）；涨停价 = 四舍五入到最小报价单位(前一日收盘价 × (1 + 涨跌幅限制比例))。","points":[["先做什么","核对目标证券所属板块的现行涨跌幅限制（以交易所现行规则为准）：沪深主板为±10%（主板风险警示股票ST/*ST自2026年7月6日起由±5%调整为±10%），科创板与创业板为±20%，北交所为±30%；注册制下新股上市后前5个交易日不设涨跌幅限制（北交所为上市首日）。"],["打个比方","涨停封单就像餐厅门口排队的黄牛，看着人多，一旦听说菜卖完了瞬间就会散光。"],["常见误区","误以为买一位置挂着几万手封单就是铁板一块，忽视未成交的委托单在撮合前可以随时撤单，盲目排单极易在炸板瞬间成交接盘。"]]},"t-196":{"title":"Blockchain & the Trilemma 区块链与不可能三角","line":"区块链是一本由许多节点共同保存、按时间顺序串起来的账本：一段时间内的交易被打包成一个“区块”，每个区块都带着上一个区块的哈希值（数据指纹），改动任何一页都会让后面的指纹全部对不上。","points":[["先做什么","先分清“链上记录”和“交易所账户余额”：后者只是交易所内部的记账。"],["打个比方","过去村里只有村长一本账，村长记错或被收买，全村都受影响；现在每家都有一本相同的账本，有人偷改自己那本，和其他人的一对就露馅。"],["常见误区","以为“上了链就是真的”。区块链只保证记录写入后难以篡改，不保证项目方写进去的内容真实，也不保证代币有价值。"]]},"t-197":{"title":"Bitcoin vs Ethereum 比特币与以太坊","line":"比特币（BTC）是第一条公链，总量上限 2100 万枚，约每 21 万个区块（大约四年）新增发行量减半，设计目标是简单、稳定的价值转移和储存。","points":[["先做什么","先分清用途：BTC 主要用于转账和储值，ETH 还被用来支付各种链上应用的手续费。"],["打个比方","比特币像一座不轻易改建的金库，规则写好后很少动；以太坊像一座不断扩建的城市，道路、楼房都在升级，机会多，施工风险也多。"],["常见误区","认为以太坊“没有上限”就等于无限通胀，或认为比特币“有上限”就只涨不跌。供应规则只是价格的一个因素，需求变化同样决定价格。"]]},"t-198":{"title":"Consensus & Chain Types 共识机制与链的类型","line":"共识机制是一条链上互不信任的节点决定“下一个区块由谁写、写什么才算数”的规则加奖惩。","points":[["先做什么","先看这条链用什么共识：PoW、PoS 或其他变体。"],["打个比方","PoW 像抢答比赛，谁先算出难题谁记这一页，作弊要买下大半台机器；PoS 像押金制，记账员先交押金，记错账押金被没收。"],["常见误区","以为 PoS 就是“存币生息”的理财产品。质押收益来自承担验证工作和罚没风险，锁定期内价格下跌同样会亏损。"]]},"t-199":{"title":"Exchange Risk: Lessons from Mt. Gox, FTX & Bybit 中心化交易所风险","line":"中心化交易所（CEX）替用户托管资产并在内部撮合交易：你在交易所看到的余额，是交易所欠你的一笔账，而不是你链上钱包里的币。","points":[["先做什么","只在交易所留下近期要交易的部分，长期持有的资产提到自己保管私钥的钱包。"],["打个比方","把币放在交易所，像把现金寄存在一家私人寄存处：平时随取随用，但寄存处倒闭或被偷，你只是排队的债权人之一。"],["常见误区","认为“大而不倒”。2014 年的门头沟（Mt. Gox）和 2022 年的 FTX 都曾是头部交易所。"]]},"t-200":{"title":"Airdrops & Sybil Attacks 空投与女巫攻击","line":"空投（Airdrop）是项目方把代币免费分发给符合条件的地址，常见依据是过去使用过产品（追溯性空投）或完成任务、积累积分。","points":[["先做什么","先确认空投公告来自项目官方渠道，警惕要求连接钱包“领取空投”的仿冒网站。"],["打个比方","空投像商场给老顾客发购物券；女巫攻击就像一个人换了一百套衣服排一百次队，商场发现后会把这些券全部作废。"],["常见误区","把空投当成无风险收益。许多“领取空投”页面本身就是钓鱼网站，一次错误签名就可能让钱包被清空。"]]},"t-201":{"title":"Layer 2 & Rollups 二层网络与 Rollup","line":"二层网络（Layer 2）把大量交易放在主链之外执行，再把压缩后的结果和证明提交回主链（Layer 1），以降低手续费、提高速度，同时尽量继承主链的安全。","points":[["先做什么","先确认你用的是哪条二层网络、属于乐观还是 ZK 类型。"],["打个比方","乐观 Rollup 像先放行再抽查，抽查期内有人举报就追回；ZK Rollup 像每批货都附带检验报告，海关核对报告就放行。"],["常见误区","以为二层网络“和主网一样安全”。多数二层仍处在逐步去中心化阶段，升级权限、排序器和桥都可能成为单点风险。"]]},"t-202":{"title":"Bridges & Oracles 跨链桥与预言机","line":"跨链桥把资产从一条链“搬”到另一条链：常见做法是在原链锁定资产，再在目标链铸造等量的包装资产（Wrapped Token），因此桥的锁仓合约和签名者一旦被攻破，目标链上的包装资产就可能失去支撑。","points":[["先做什么","使用跨链桥前，查清它由多少签名者控制、是否经过审计、历史上是否出过事故。"],["打个比方","跨链桥像在两地之间寄存兑换：你把金条存进 A 城保险库，在 B 城拿到一张提货券；保险库被盗，提货券就成了废纸。"],["常见误区","以为包装资产和原生资产完全等价。包装 ETH 只是一张由桥背书的凭证，桥出事时两者价格会明显分离。"]]},"t-203":{"title":"Smart Contracts & Token Approvals 智能合约与代币授权","line":"智能合约是部署在区块链上、满足条件就自动执行的程序。","points":[["先做什么","签名前看清钱包弹窗：是普通转账、授权（approve），还是离线签名许可（Permit）。"],["打个比方","授权像把家里一把备用钥匙交给保洁公司：方便它随时进门打扫，但公司跑路或钥匙被偷，家里的东西就危险了。"],["常见误区","以为“不点转账就不会丢钱”。授权和离线签名本身就能把动用代币的权限交给对方，许多钓鱼盗币都发生在用户以为只是“登录”或“验证”的那一次签名。"]]},"t-204":{"title":"Tokenomics: Supply, FDV & Unlocks 代币经济学：供应、FDV 与解锁","line":"代币经济学研究代币如何发行、分配、释放和被使用。","points":[["先做什么","同时看流通市值和 FDV，算出流通量占最大供应量的比例。"],["打个比方","像一家公司只把 10% 的股票拿出来交易，其余 90% 在创始人和投资人手里，几年内陆续可以卖。"],["常见误区","只看单价觉得“便宜”。0.01 美元的代币如果供应量有 1 万亿枚，FDV 照样高达 100 亿美元。"]]},"t-205":{"title":"DEXs & AMMs 去中心化交易所与自动做市商","line":"去中心化交易所（DEX）让用户直接用自己的钱包和智能合约交易，不需要把资产交给交易所托管。","points":[["先做什么","交易前看池子深度和预估的价格冲击，大额交易拆分或改用聚合器。"],["打个比方","资金池像一个两边放着苹果和橙子的天平，你拿走苹果就要放进橙子，天平越倾斜，再拿苹果就越贵。"],["常见误区","以为 DEX 上的价格就是“市场价”。浅池子里的价格很容易被一笔交易推高或砸低，只代表这个池子当下的比例。"]]},"t-206":{"title":"DeFi Lending & Liquidation 去中心化借贷与清算","line":"去中心化借贷协议（如 Aave、Compound）让用户存入资产赚取利息，或以存入资产作抵押借出其他资产。","points":[["先做什么","借款前算出清算价格：抵押品价格跌到多少时健康因子等于 1。"],["打个比方","像把金条押在当铺借钱：当铺只看金价，金价跌到一定程度就会自动卖掉一部分金条还债，而且按折扣价卖。"],["常见误区","只看存款利率高就把资产存进去，忽略协议漏洞、预言机异常和资产脱锚风险。高利率往往意味着更高的风险或更少的需求方。"]]},"t-207":{"title":"Staking, Liquid Staking & Restaking 质押、流动性质押与再质押","line":"质押是把代币锁定在权益证明网络中参与验证、获得奖励。","points":[["先做什么","先分清自己持有的是原生代币、流动性质押凭证（LST），还是再质押凭证（LRT）。"],["打个比方","质押像把钱存成定期；流动性质押像拿到一张可转让的存单；再质押像把这张存单再押给别人担保，赚第二份利息。"],["常见误区","把“质押收益”当成无风险利息。它来自承担验证与罚没风险。"]]},"t-208":{"title":"Greeks I: Delta & Gamma 希腊字母一：Delta 与 Gamma","line":"Delta（Δ）衡量标的资产价格每变动 1 个单位时，期权理论价格随之变动的幅度；看涨期权 Delta 位于 0 到 1 之间，看跌期权位于 -1 到 0 之间。","points":[["先做什么","在期权报价链（Option Chain）中找到目标合约的 Delta 与 Gamma 列，确认看涨为正、看跌为负的符号方向。"],["打个比方","如果把标的资产价格变化比作汽车行驶的距离，期权价格变化就是速度表读数：Delta 相当于当前的车速（每走 1 公里期权变动多少），而 Gamma 就相当于踩油门的加速度（车速本身变快了多少）。"],["常见误区","误以为买入时看到的 Delta 在整个持仓期间恒定不变，或者把 Delta 0.30 直接等同于现实世界里 30% 的获利概率。"]]},"t-209":{"title":"Greeks II: Theta & Vega 希腊字母二：Theta 与 Vega","line":"Theta（Θ）衡量在其他条件不变时，每经过 1 天时间流逝，期权理论价格因时间价值衰减而减少的金额（对期权买方通常显示为负数）。","points":[["先做什么","在期权报价链中读取 Theta 与 Vega，注意 Theta 按每日计算，而 Vega 对应隐含波动率每 1 个百分点的变动。"],["打个比方","可以把期权时间价值比作一块放在室外的冰块：Theta 是每天自然融化的水滴，越接近最后期限冰块化得越快；Vega 则是室外的气温变化，隐含波动率上升好比气温骤降让冰块重新结霜变厚，隐含波动率骤降则像烈日暴晒让冰块瞬间缩水。"],["常见误区","误以为卖出期权稳收 Theta 是无风险收租，或者以为只要股价不动期权价格就只按 Theta 缓慢减少。"]]},"t-210":{"title":"Implied Volatility, IV Rank & Volatility Crush 隐含波动率、IV Rank 与波动率压缩","line":"隐含波动率（IV）是将期权当前市场成交价代入定价模型反推出来的年化预期波动率。","points":[["先做什么","先对比当前 IV 与标的过去 52 周的区间，计算或查看 IV Rank 与 IV Percentile，而不单看孤立的 IV 原始百分比。"],["打个比方","IV 好比台风来临前海鲜市场的实时菜价；IV Rank 是看今天菜价处于全年最高价与最低价标尺的几分之几位置；IV Percentile 是数过去一年里有几天菜价比今天便宜；而波动率压缩（IV Crush）就像台风警报解除的清晨，恐慌囤货消失，菜价瞬间跳水回落。"],["常见误区","看到 IV Rank 高达 80% 就机械认为波动率马上会跌而盲目裸卖期权，或者财报前只赌正股涨跌方向而忽视 IV Crush。"]]},"t-211":{"title":"Volatility Smile & Skew 波动率微笑与偏斜","line":"波动率微笑（Volatility Smile）与波动率偏斜（Volatility Skew，又称波动率歪笑 Smirk）指同一标的、同一到期日的不同行权价期权，其隐含波动率（IV）并非处于同一条水平线上：当深价内与深价外两侧行权价的 IV 均高于平值（ATM）期权、图形呈两端上翘的 U 型时称为“波动率微笑”；当某一侧（如股指期权中较低行权价的虚值看跌一侧）IV 显著高于另一侧、曲线呈单边倾斜时称为“波动率偏斜”。","points":[["先做什么","固定同一个到期日，以行权价（或 Delta）为横轴、隐含波动率（IV）为纵轴，观察曲线形态是 U 型对称微笑还是单边倾斜。"],["打个比方","这就像给不同部位买意外险：在股票市场里，机构投资者长期持有大量现货股票，最害怕突然发生股灾崩盘，因此争相抢购低行权价的虚值看跌期权当“防跌地震险”，把低行权价一侧的保费（IV）买得远比高行权价一侧昂贵，画出来就像一边嘴角高高翘起的“歪笑（偏斜）”。"],["常见误区","看到低行权价虚值看跌期权的 IV 远高于平值，就以为它“定价错误”而去大量裸卖虚值看跌期权。"]]},"t-212":{"title":"Covered Calls & Protective Puts 备兑看涨与保护性看跌","line":"备兑看涨（Covered Call）指在持有足额标的现货（如每 100 股正股）的同时，卖出 1 张对应数量的看涨期权（Call），以放弃行权价之上的潜在涨幅为代价收取权利金，区别于无现货担保的裸卖看涨（见本站「Options Basics 期权入门」一课）。","points":[["先做什么","构建备兑看涨前，先核对账户中是否持有足额现货，避免无意间变成高风险的裸卖看涨。"],["打个比方","备兑看涨好比房东把自住的投资房挂牌签了一份“带定金的优先认购协议”：你立刻收下一笔定金（权利金）补贴日常持有成本，但如果房价暴涨超过约定价，你就得按约定价把房子卖给对方；保护性看跌则好比给这栋房子买了一份财产底线险：多掏一笔保费，换来房价跌破理赔线时有人按保底价兜底。"],["常见误区","误以为备兑看涨（Covered Call）是既能收租又能防大跌的稳健策略。"]]},"t-213":{"title":"Vertical Spreads 垂直价差","line":"垂直价差（Vertical Spread）指针对同一标的资产、选择完全相同的到期日，同时买入 1 张某行权价的期权并卖出 1 张同类型（同为看涨或同为看跌）但不同行权价的期权。","points":[["先做什么","确认两条腿属于同一标的、同一到期日、同一期权类型，仅行权价一高一低。"],["打个比方","垂直价差就像买了一张高档演出的门票，同时把座位附赠的“加时返场观看权”转卖给别人：你用转卖收来的钱抵扣了一部分门票支出，降低了回本门槛，代价是如果演出真的加时大狂欢，超出返场界限后的那部分精彩就不再归你享有。"],["常见误区","误以为垂直价差因为风险封顶就可以重仓满买，或者忽略到期日股价刚好停在两个行权价之间时的交割与指派风险。"]]},"t-214":{"title":"RWA: Real-World Assets On-Chain 现实资产上链","line":"将国债、房地产、应收账款等链下传统资产的所有权或收益权通过法律架构与智能合约映射为链上代币，使其可在区块链上持有、流转与组合的模式。","points":[["先做什么","识别底层资产：区分高流动性国债、货币基金与低流动性私人信贷或房产。"],["打个比方","好比剧院把大楼租金收益拆成编号电子凭据：大楼仍归现实物业与法律管辖，凭据让份额转让更便捷，但若租客违约，电子凭据并不能凭空变出房租。"],["常见误区","以为资产上链就抗审查——合规 RWA 合约常保留司法冻结权限。"]]},"t-215":{"title":"DePIN: Token-Incentivised Infrastructure 用代币共建基础设施","line":"去中心化物理基础设施网络（DePIN），指通过代币激励引导全球个人或节点贡献无线热点、传感器、存储或算力等硬件资源，协同建设与运营物理基础设施的网络模式。","points":[["先做什么","区分资源类型：判断属于物理资源网（无线、传感器）还是数字资源网（存储、算力）。"],["打个比方","就像众包气象网：给居民发积分补贴在阳台装传感器上传数据，比气象局自建省钱，但若没有农企或物流公司付费买数据，积分就会因缺乏买单方而贬值。"],["常见误区","按初期产量与高币价静态算回本，忽视节点稀释与通胀抛压。"]]},"t-216":{"title":"On-Chain Identity: DID & SBT 链上身份：DID 与 SBT","line":"去中心化标识符（DID）是由用户自主掌握私钥与验证方法的数字身份标准；灵魂绑定代币（SBT）则是绑定在特定账户上、不可转让的链上凭证，用于记录资历、信誉或成员身份。","points":[["先做什么","区分标识与凭证：明确 DID 是底层账户标识，而 VC 与 SBT 是挂载的属性证明。"],["打个比方","DID 像自己保管钥匙的电子档案袋，SBT 像印在里面的毕业章：纪念币可买卖，但毕业章锁定后无法过户，既能证明经历，也意味着若把档案袋公开，外人能顺着印章看清你的过往。"],["常见误区","把 .eth 域名等同于完整去中心化身份——域名只是可读别名，可转让且非资质证明。"]]},"t-217":{"title":"New Token Standards: ERC-404, 6551, 3525 新代币标准：ERC-404、6551、3525","line":"在以太坊同质化代币（ERC-20）与非同质化代币（ERC-721）基础上演进出的新型资产协议，分别探索图币混合流动性（ERC-404）、代币绑定账户（ERC-6551）与半同质化金融凭证（ERC-3525）。","points":[["先做什么","识别标准性质：在区块浏览器核对合约属于已定稿的 EIP（3525）、仍在审阅的 EIP（6551），还是未走 EIP 流程的实验协议（404）。"],["打个比方","若 ERC-20 是纸钞、ERC-721 是邮票，ERC-404 像集齐整张券自动发邮票、卖掉零头又把邮票收回销毁；ERC-6551 是给邮票配了随身储物箱；ERC-3525 则像同批次可拆分面额的储值卡。"],["常见误区","以为带 ERC 前缀都经官方审批——ERC-404 未走正式 EIP 流程。"]]},"t-218":{"title":"AI × Web3 AI × Web3 AI × Web3","line":"将人工智能（AI）的推理与自动化能力和区块链的去中心化激励、密码学验证与链上支付体系相结合的交叉技术方向。","points":[["先做什么","识别业务层级：区分底层算力数据网、中间层验证协议（zkML）与上层 AI 智能体。"],["打个比方","AI 像会自动炒菜的厨师，区块链像公开食材账本与自动收银台：厨师让流程自动化，账本按贡献给供货商分账，但若有人塞入伪造指令字条（提示词注入），厨师可能把收银台的钱误转给外人。"],["常见误区","以为分布式民用显卡能立即替代超算中心同步训练千亿大模型。"]]},"t-219":{"title":"DeSci: Decentralised Science 去中心化科研","line":"去中心化科学（DeSci），指利用区块链、去中心化自治组织（DAO）、灵魂绑定凭证与知识产权代币化（IP-NFT）重构科研经费筹集、同行评审、数据开源与成果转化的运动。","points":[["先做什么","审视同行评审：核查科研 DAO 是否有专业学者把关立项，而非纯靠持币大户投票。"],["打个比方","传统科研像排长队向少数委员会申经费、交过路费发论文；DeSci 像开放科研合作社，把实验记录存进公共档案馆并用电子凭证共享未来专利分成——但若投票人看不懂实验方案，资金可能流向伪科学。"],["常见误区","以为持有科研代币就自动获得各国法院直接承认的药品专利权。"]]},"t-220":{"title":"A Map of the Web3 Industry 行业地图","line":"按技术层级与业务职能对 Web3 行业生态进行的系统划分，涵盖底层基础设施层、中间件与工具层、应用层以及外围服务与研究生态。","points":[["先做什么","梳理四层坐标：判断目标项目处于底层公链、中间件、应用层还是研究合规服务。"],["打个比方","把 Web3 想象成数字港口城市：公链与扩容网是修路架电网的工程队，预言机与审计公司是水厂和消防安检局，交易借贷应用是街面银行商铺，而研究员、运营与法务则是报社、向导与律所。"],["常见误区","以为只有写智能合约才能入行——全栈开发、产品、设计、研究与运营同样关键。"]]},"t-221":{"title":"Everyday Tools & Industry Jargon 常用工具与行业黑话","line":"日常参与和研究 Web3 必备的五类基础工具（区块浏览器、数据看板、自托管钱包、多签钱包、测试网水龙头）以及高频社区与链上术语速查。","points":[["先做什么","用浏览器查交易：粘贴 TxHash 或合约地址，核实状态、Gas 消耗及源码是否开源验证。"],["打个比方","五类工具像航海仪表盘：区块浏览器是看清海底礁石的声呐，数据看板是气象雷达，个人钱包是船长钥匙，多签钱包是需三位大副同时拧钥匙的保险柜，测试网水龙头则是陆地模拟舱的免费燃料。"],["常见误区","在搜索引擎点带广告标识的钱包或浏览器链接，极易误入钓鱼站泄露助记词。"]]},"t-222":{"title":"Technical Roles in Web3 技术岗位全景","line":"围绕区块链协议、智能合约、安全审计与去中心化应用前后端开发所形成的技术职业体系，分为链上原生研发与 Web2.5 融合工程两大路径。","points":[["先做什么","选择切入路径：有前后端基础可从 Web3 全栈与数据索引切入，专注底层可攻合约与审计。"],["打个比方","传统网页开发像装修随时可停业翻新的餐厅；智能合约开发与审计则像建造并检验发射升空的太空舱——升空后极难返厂拆修，一处螺丝松动都可能在高压下造成严重损失。"],["常见误区","照搬模板发币却不写单元测试与边界测试，上线易遭黑客攻击。"]]},"t-223":{"title":"Operations & Business Roles in Web3 运营与商务岗位全景","line":"围绕 Web3 协议的社区建设、用户增长、内容研究、生态商务拓展（BD）与去中心化治理协调所形成的非技术职业体系。","points":[["先做什么","找准细分方向：按外语沟通、深度写作、数据分析或谈判特长选择社区、内容、研究或 BD。"],["打个比方","若工程师是造开源火车头的人，内容与研究岗就是写乘客指南的编辑，社区运营是车厢里维持秩序并防扒手的乘务长，而商务拓展（BD）则是去和沿途车站谈判接轨的联络官。"],["常见误区","把运营当成刷屏喊口号或买假粉，缺乏产品理解与真实留存转化。"]]},"t-224":{"title":"On-Chain Derivatives 链上衍生品","line":"部署在区块链智能合约或应用链上的衍生品协议，主要提供无需交割日的永续合约交易，通过链上抵押按金托管与公开清算规则实现去中心化杠杆与对冲。","points":[["先做什么","识别撮合架构：区分应用链限价订单簿模式与资金池（LP）对手方预言机定价模式。"],["打个比方","中心化交易所像把筹码交给柜台保管的封闭俱乐部；链上订单簿型像把筹码锁在透明保险箱里、由电子公告栏撮合买卖；而资金池型像众人凑钱开公共资金池直接和交易者做对手盘——交易者亏钱时池子分红，交易者单边大赚时池子就要赔付。"],["常见误区","以为向衍生品资金池（LP）注资仅稳收手续费——LP 是交易者的对手盘，单边行情下交易者大赚会消耗池子本金。"]]},"t-225":{"title":"Yield Aggregators & Restaking 收益聚合与再质押","line":"收益聚合器是通过智能合约自动执行复利复投与跨协议调仓的链上资产管理工具；再质押则是将已质押的权益资产二次用于担保外部中间件或网络以获取叠加收益的机制。","points":[["先做什么","追溯真实收益来源：区分可持续的共识奖励、交易手续费与高通胀代币短期补贴。"],["打个比方","收益聚合器像邻居合雇自动收租并复投铺面的管家以省去各自跑腿费；再质押则像把同一套房产证同时押给三家商铺做担保——平时拿三份补贴，但只要任一商铺违约，这套唯一的房产就会被查封扣款。"],["常见误区","只看表面高年化收益率（APY）忽视奖励币贬值。"]]},"t-226":{"title":"Aggregators & Launchpads 聚合器与代币首发平台","line":"交易聚合器是通过智能路由算法在多个去中心化交易所间拆分订单以降低滑点与成本的入口工具；代币首发平台（Launchpad / IDO）则是协助新项目在链上进行早期代币公开发售与募集资金的平台。","points":[["先做什么","对比路由净到手额：确认多跳拆单省下的滑点在扣除额外燃料费后仍优于单池兑换。"],["打个比方","交易聚合器像机票比价拆单平台，不开航空公司但能把团队票拆到三家航司拿最低总价；Launchpad 像商场要求先办昂贵储值卡才可摇号买限量商品——若储值卡本身大跌或商品很快大批补货降价，摇中号反而亏钱。"],["常见误区","以为小额兑换用聚合器总能省钱——小额拆单增加的多跳燃料费可能超过省下的滑点。"]]},"t-227":{"title":"Concentrated Liquidity & Liquidity Management 集中流动性与流动性管理","line":"允许流动性提供者（LP）将资金指定部署在自定义价格区间（Ticks）内以大幅提升资金利用效率的做市机制，以及围绕区间调仓与无常损失对冲展开的流动性管理策略。","points":[["先做什么","按波动率设定区间：稳定币对可设极窄区间，高波动币种需留出足够宽的安全价格带。"],["打个比方","全区间做市像在几百公里高速路上每隔一公里摆无人售水摊，多数摊位没人路过；集中流动性则是把水全摆在最繁忙的服务区门口，卖水效率极高，但一旦高速改道（价格跑出区间），摊位前就空无一人，得自己花油费把货车搬去新路段。"],["常见误区","盲目设极窄区间追求高年化展示值——价格微幅波动即出界停息且放大无常损失。"]]},"t-228":{"title":"GameFi: On-Chain Game Economies 链上游戏经济","line":"将区块链资产确权与去中心化金融机制融入电子游戏，使游戏角色、道具或代币可在链上持有与流转的赛道，涵盖早期边玩边赚（P2E）及后续链上游戏经济探索。","points":[["先做什么","审视价值消耗闭环：检查代币消耗（Sink）是仅用于繁殖产出工具，还是存在真实娱乐性消费。"],["打个比方","早期 P2E 像规定“买母鸡进场下蛋、鸡蛋主要用来孵小母鸡卖给新游客”的农场：只要每天有新游客高价买小鸡，大家账面都盈利；可一旦没有新游客进场，没人再孵小鸡，所有人同时把鸡蛋拉去集市甩卖，蛋价和母鸡价格就会双双雪崩。"],["常见误区","把新玩家买 NFT 的资金流当成游戏外部造血收入。"]]},"t-229":{"title":"SocialFi: Tokenising Social Graphs 社交关系代币化","line":"将去中心化身份、链上社交图谱与代币经济机制融入社交网络，使创作者与用户能够自主拥有社交关系并探索内容、关注度与影响力资产化的赛道。","points":[["先做什么","区分图谱与投机应用：判断项目侧重于可跨客户端迁移的底层图谱，还是短期联合曲线炒作。"],["打个比方","传统社交平台像租商场铺位，顾客名单归商场经理管，退租带不走熟客；去中心化社交图谱让你自带可搬家的客户名册；而联合曲线门票则像“每多卖一张就自动加速涨价”的会员卡——黄牛机器人在第一秒买走前十张，等粉丝高价接盘后黄牛一抛售，卡价便跌回谷底。"],["常见误区","把联合曲线陡峭涨幅当成充沛市场深度——大户集中卖出时价格会按同一公式急速崩塌。"]]},"t-230":{"title":"DAOs & On-Chain Governance 与链上治理","line":"去中心化自治组织（DAO），指通过公开智能合约与治理代币投票共同管理国库资金与协议参数的组织形态，通常结合治理论坛、链下快照、时间锁与多签执行。","points":[["先做什么","追踪完整提案流程：查看提案是否走完论坛讨论（RFC）、链下快照（Snapshot）与链上代码投票。"],["打个比方","DAO 治理像业主按面积投票管理公共维修基金：论坛是业主群商议，Snapshot 是免费问卷摸底，链上投票是正式划款单，而时间锁则规定“任何大额动账决议通过后先公示 48 小时才放款”——万一有人串通通过了私吞基金的提案，其他业主至少有 48 小时撤走资金。"],["常见误区","以为叫 DAO 就完全去中心化——部分项目无链上执行合约或时间锁，资金仍由团队多签单方控制。"]]},"t-231":{"title":"Prediction Markets & InfoFi 预测市场与 InfoFi","line":"信息金融（InfoFi），指利用链上预测市场、注意力激励或声誉质押等金融机制对现实事件概率与信息价值进行发现、定价与验证的赛道。","points":[["先做什么","细读事件结算细则：下注前逐字核对判定数据源、截止时间及边界情况定义。"],["打个比方","网络投票喊错不亏钱；预测市场则像凭结果兑付 1 美元的二元券：当市场花 0.70 美元买“明天下雨”时，该价格就反映了场内资金判断的 70% 降雨概率；但若池子只有十块钱，花五块就能把概率拉到九成，且雨夹雪算不算下雨还得靠预言机投票。"],["常见误区","把浅池子里的份额价格当成客观科学概率——冷门市场中单一地址用少量资金即可制造高概率假象。"]]},"t-232":{"title":"Phishing Signatures, Address Poisoning & Fake Airdrops 钓鱼签名、地址投毒与假空投","line":"链上钓鱼是骗子不直接要你的钱，而是诱导你在钱包里签下一次授权或签名，或者把钱转到看起来像正确地址的假地址。","points":[["先做什么","签名前读清钱包弹窗：是转账、授权（approve）、许可签名（Permit），还是只是登录消息；看不懂就先不签。"],["打个比方","钓鱼签名像有人递来一张写着“签到表”的纸，其实是授权书；地址投毒像有人在你的通讯录里加了一个和朋友同名、只差中间几位号码的联系人；假空投像信箱里突然多了一张“中奖通知”，让你去某个网址领奖。"],["常见误区","以为“没花钱、只是签个名”就安全。"]]},"t-233":{"title":"Pig Butchering, Rug Pulls & Ponzi Schemes 杀猪盘、跑路项目与庞氏骗局","line":"三类以“投资”为名的骗局：杀猪盘（先在网上建立感情或信任，再带你去假平台“投资”，账面越赚越多却提不出钱）；跑路项目（项目方募到钱或拉高币价后撤走资金池、增发代币或让代币无法卖出，然后消失）；庞氏骗局（用后来者的钱支付先来者的“收益”，靠不断拉新维持，新钱一停就崩）。","points":[["先做什么","先算账：把承诺的日收益或月收益按复利换算成年化，数字高得离谱就是危险信号。"],["打个比方","杀猪盘像一个陪你聊了几个月的“朋友”，带你进一家只有他认识的“银行”，存折上的数字天天涨，但柜台总在“系统维护”；跑路项目像一家开业大酬宾的商场，收完预付卡后连夜搬空；庞氏骗局像击鼓传花，花传到没有新人接时，最后拿着的人全部受损。"],["常见误区","把账面收益当成真钱，或为了“提出之前的钱”继续交费。账面数字由骗子控制，每多交一次只是多损失一次。"]]},"i-1":{"title":"CPI 消费者物价指数","line":"跟踪美国城市居民购买一篮子商品和服务要花多少钱。","points":[["怎么读","在 Table 1 找 All items；先看季调的1个月变化，再看12个月变化和住房、能源分项。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","同比下降不等于生活用品降价；基期那个月很高也会让同比自然回落。"]]},"i-2":{"title":"核心 CPI","line":"从CPI中去掉食品和能源，用来观察容易被油价、菜价盖住的价格趋势。","points":[["怎么读","在CPI Table 1找 All items less food and energy；把住房、医疗及商品分项一起看。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","核心CPI不是美联储2%目标的正式衡量口径；目标参考整体PCE。"]]},"i-3":{"title":"PCE 物价指数","line":"衡量美国居民消费相关商品和服务的价格，覆盖范围和权重与CPI不同，例如包含部分由雇主、政府替居民支付的医疗消费。","points":[["怎么读","打开 Personal Income and Outlays，在价格表找 PCE price index，别选 real PCE；再核对月率和年率。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","PCE物价指数和个人消费支出金额是不同东西；前者看价格，后者还受购买数量影响。"]]},"i-4":{"title":"核心 PCE","line":"PCE物价指数剔除食品和能源后的分项，常用来观察通胀是否持续降温。","points":[["怎么读","在BEA价格表找 PCE excluding food and energy；记录最新月率、修订后的前月及同比。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","同比与环比给出不同方向时先解释基数和修订；不要把一月数据直接乘12当精确年率。"]]},"i-5":{"title":"PPI 生产者物价指数","line":"跟踪美国国内生产者出售商品和服务收到的价格。","points":[["怎么读","在PPI Table 1找 Final demand，再分 Final demand goods 和 services，不要把中间需求当总PPI。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","PPI上涨不会按相同百分比传到CPI；企业可能压利润、换供应商或晚些才调价。"]]},"i-6":{"title":"核心 PPI","line":"这里明确采用最终需求剔除食品和能源口径。","points":[["怎么读","在PPI表中找 Final demand less foods and energy；另一个 less foods, energy, and trade services 是不同系列，不能混用。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","数据日历中“核心PPI”定义可能不同；比较预期前必须对齐同一口径。"]]},"i-7":{"title":"进口物价指数","line":"跟踪美国从国外买入商品和部分服务的价格变化，以美元计价。","points":[["怎么读","打开 Import and Export Price Indexes，先读 All imports，再读 Imports excluding fuels；核对未季调标记。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","进口物价指数通常不含关税本身，不能把它当进口商含税总成本账单。"]]},"i-8":{"title":"出口物价指数","line":"跟踪美国卖到国外的商品和部分服务的美元价格。","points":[["怎么读","在国际物价报告的出口价格表找 All commodities（全部出口商品），再分别看 Agricultural commodities 和 Nonagricultural commodities。"],["怎么影响市场","出口价格首先影响美国出口商的收入和海外买家的购买力，但还要乘上卖出的数量才接近销售额。"],["常见误区","这不是贸易顺差，也不是出口金额；商品构成、美元和全球供需会一起影响它。"]]},"i-9":{"title":"ECI 雇佣成本指数","line":"衡量雇主雇一个人每小时支付的工资和福利成本怎样变。","points":[["怎么读","在ECI表找 Civilian workers 的 Total compensation，并分开 wages and salaries、benefits。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","季度0.8%不等于同比0.8%；工资成本上涨也可能由生产率增长抵消。"]]},"i-10":{"title":"密歇根大学通胀预期","line":"调查美国消费者觉得未来物价每年会涨多少。","points":[["怎么读","在密歇根大学报告找 Year-ahead inflation expectations 与 Long-run inflation expectations，并核对初值或终值。"],["怎么影响市场","传导不是数字直接推股价，而是：价格压力改变对美联储利率路径的判断→影响美债收益率和企业借钱成本→投资者重新计算未来利润今天值多少钱。"],["常见误区","不要把消费者预期当央行预测；调查有抽样误差，初值和终值可能不同。"]]},"i-11":{"title":"非农就业人数","line":"美国非农机构工资单上的岗位数量；常说的新增非农是本月比上月多了多少岗位，不是就业总人口。","points":[["怎么读","在 Employment Situation 找 Total nonfarm payroll employment；Table B-1读本月变化和前两月修订。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","一人有两份工作可能算两个岗位；非农岗位调查与家庭调查中的就业人数不同。"]]},"i-12":{"title":"失业率","line":"在正在工作或积极找工作的人里，没有工作、可以工作且符合找工作条件的人占多少。","points":[["怎么读","在就业报告 Table A-1找 Unemployment rate，同时读 Civilian labor force 和 Employment-population ratio。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","不再找工作的人一般退出劳动力，不计入U-3失业分子；失业率下降也可能并非好消息。"]]},"i-13":{"title":"劳动参与率","line":"16岁及以上非机构平民人口中，正在工作或积极找工作的人占比；它看“有多少人参加劳动市场”。","points":[["怎么读","在就业报告 Table A-1找 Participation rate；再到BLS数据库或FRED查25至54岁（prime-age）参与率，避免把退休老龄化全当周期恶化。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","0.2个百分点不等于增长0.2%；学生、退休及照护安排会影响参与率。"]]},"i-14":{"title":"平均时薪","line":"私人非农雇员平均每小时税前工资。","points":[["怎么读","在就业报告 Table B-3找 Average hourly earnings of all employees, total private；不要误选只含生产和非管理人员的另一系列。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","这是名义税前工资；要知道购买力，需要结合物价，不能把美元工资增长直接当实际收入增长。"]]},"i-15":{"title":"平均每周工时","line":"私人非农员工每周平均工作几小时。","points":[["怎么读","在就业报告 Table B-2找 Average weekly hours, all employees, total private；并观察制造业加班工时。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","天气、罢工和行业构成会扰动单月工时；不能由少0.2小时直接推出衰退。"]]},"i-16":{"title":"初请失业金人数","line":"一周内第一次提出失业保险申请的件数，是裁员压力较快的温度计，但不是全体新失业人数。","points":[["怎么读","在劳工部报告找 Initial claims 的 Advance 和 Revised，再读4-week moving average，确认统计周。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","申请不等于申请获批；未覆盖的自雇者和不申请者不完整计入。"]]},"i-17":{"title":"续请失业金人数","line":"已经申请过、仍继续领取或申请失业保险的人次规模，帮助看失业者能否较快找到新工作。","points":[["怎么读","在劳工部报告找 Insured unemployment / Continuing claims；它的统计周一般比初请再落后一周，别拿错日期。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","领取期限耗尽可能让续请下降，即使人还没有工作；续请并不等于全部失业人口。"]]},"i-18":{"title":"JOLTS 职位空缺","line":"调查月最后一个工作日，企业仍有、可以在30天内开始且正在积极招聘的职位空缺。","points":[["怎么读","在JOLTS Table 1看 Total nonfarm job openings；再看招聘人数和裁员，区分少招人与多裁人。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","职位空缺不等于新增非农；空缺广告也不代表每个岗位最终都会招人。"]]},"i-19":{"title":"JOLTS 主动离职率","line":"员工自愿离职人数占就业人数的比例。","points":[["怎么读","在JOLTS的 Quits 表找 Total nonfarm rate，不要只看人数；并与 Hires rate 对照。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","退休、调职等不都属于Quits；不同离职分类不要混为裁员。"]]},"i-20":{"title":"ADP 私营部门就业人数","line":"用ADP薪资处理数据估算美国私人部门就业变化。","points":[["怎么读","打开 ADP National Employment Report，读 Private employment 和行业、企业规模分项；将Pay Insights与岗位数分开。"],["怎么影响市场","就业和工资支撑居民消费，消费又关系企业收入；与此同时，过紧的劳动市场可能增加工资和服务通胀，让美联储更不急着降息。"],["常见误区","2022年重构后的ADP报告不以预测BLS非农为目标；跨版本比较需注意方法变化。"]]},"i-21":{"title":"GDP 国内生产总值","line":"美国境内一段时间生产的最终商品和服务总量，实际GDP尽量剔除价格上涨影响；它是经济产出的总账。","points":[["怎么读","打开GDP最新报告找 Real GDP；Table 1看增长，贡献表区分消费、投资、净出口和政府支出。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","季度折年率3%不是这个季度真增长3%；进口减少可能抬高GDP算式，却不一定说明国内需求强。"]]},"i-22":{"title":"GDI 国内总收入","line":"从生产过程赚到的工资、利润等收入加总看同一个经济体。","points":[["怎么读","在GDP报告找 Gross domestic income，或BEA互动NIPA表1.17.1；确认 Real 而不是 current-dollar。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","GDI不是居民可支配收入；它还包含企业等部门的生产收入，且发布时间可能晚于GDP初值。"]]},"i-23":{"title":"ISM 制造业 PMI","line":"对制造业采购经理问订单、产出、就业等比上月好还是差，再合成指数。","points":[["怎么读","在ISM Manufacturing报告看 headline PMI，再读 New Orders、Production、Employment、Prices、Supplier Deliveries。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","50不是整个美国经济必然衰退的界线；配送变慢也可能由供给受阻造成。"]]},"i-24":{"title":"ISM 服务业 PMI","line":"调查服务业采购管理人员，覆盖商业活动、新订单、就业、交付等。","points":[["怎么读","在ISM Services报告找 Services PMI、Business Activity、New Orders、Employment 和 Prices。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","ISM服务业总指数不是单独Business Activity指数；不要与标普服务业标题数直接当同一公式。"]]},"i-25":{"title":"标普全球美国制造业 PMI","line":"标普全球对美国制造业企业的月度调查。","points":[["怎么读","打开S&P PMI新闻发布页，选 United States，找 Manufacturing PMI；先确认flash还是final，再看新订单、产出和价格文字。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","标普与ISM结果不同可以同时成立；不要拿其中一个预期去对比另一个实际值。"]]},"i-26":{"title":"标普全球美国服务业 PMI","line":"标普美国服务业标题指标主要看商业活动比上月怎样变化；它不等于把所有服务业分项简单平均。","points":[["怎么读","在United States PMI报告找 Services PMI Business Activity Index，区分 Composite Output Index；再读新增业务和收费价格。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","综合PMI混合制造业和服务业，不能冒充服务业；指数低于预期不一定代表当月产量减少。"]]},"i-27":{"title":"工业产出","line":"衡量美国制造业、矿业和公用事业的实际产出，尽量剔除价格。","points":[["怎么读","在美联储G.17找 Industrial production，再分 Manufacturing、Mining 和 Utilities；查看月率与修订。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","天气可让公用事业大幅波动；工业产出不是制造业订单，也不是GDP全部。"]]},"i-28":{"title":"产能利用率","line":"工业实际产出相对于可持续产能用了多少。","points":[["怎么读","在G.17找 Capacity utilization, total industry，并与长期均值、制造业利用率及产出一起看。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","利用率高并不保证企业利润高；能源成本、维护与不同产业正常水平都不同。"]]},"i-29":{"title":"耐用品订单","line":"美国制造商接到的预计使用三年或以上商品的新订单，如设备、汽车和飞机；反映未来生产需求的一部分。","points":[["怎么读","在Census M3先开 Advance report on durable goods，读 New orders，再读 Excluding transportation。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","订单可能取消或延迟，订单不是已出货也不是利润；金额上升还可能包含涨价。"]]},"i-30":{"title":"核心资本品订单","line":"通常指剔除飞机的非国防资本品订单，想更接近企业购买设备的意愿，减少军工和大飞机合同干扰。","points":[["怎么读","在M3找 Nondefense capital goods excluding aircraft 的 New orders；旁边Shipments是另一指标。"],["怎么影响市场","经济活动影响企业销售和利润，这是股票的收入路径；若需求强得让通胀黏住，又会抬高预期利率和折现率，这是估值路径。"],["常见误区","“核心”不是剔除所有波动项目；不要用订单直接替代GDP设备投资所用的出货资料。"]]},"i-31":{"title":"零售销售","line":"零售商及餐饮服务的销售金额，主要看居民买商品花钱情况，覆盖不了医疗、住房等大部分服务消费。","points":[["怎么读","在Census Retail打开 Advance Monthly Sales，先读 Total，再看 Excluding motor vehicles 和行业表。"],["怎么影响市场","居民花钱会成为企业营业收入，持续的实际收入又能支撑未来消费，所以数据会影响美股盈利预期。"],["常见误区","报告不直接剔除价格；网上购物是销售渠道，不等于所有非实体消费和服务。"]]},"i-32":{"title":"零售销售控制组","line":"常用口径从零售销售剔除汽车、汽油、建材及餐饮服务，帮助观察较贴近GDP商品消费估计的一组销售。","points":[["怎么读","在官方Advance表核对总额和四个排除行业；第三方日历的 Retail control 须确认完全相同口径。"],["怎么影响市场","居民花钱会成为企业营业收入，持续的实际收入又能支撑未来消费，所以数据会影响美股盈利预期。"],["常见误区","控制组不是实际消费，也不是官方所有服务消费；不同平台的“核心零售”可能仅剔除汽车。"]]},"i-33":{"title":"实际个人消费支出","line":"把消费金额中的价格变化尽量去掉，观察美国居民实际消费的商品和服务数量，是判断需求的重要总账。","points":[["怎么读","在BEA Personal Income and Outlays找 Real PCE，并区分 goods 与 services；别把PCE price index当消费量。"],["怎么影响市场","居民花钱会成为企业营业收入，持续的实际收入又能支撑未来消费，所以数据会影响美股盈利预期。"],["常见误区","链式美元各分项不一定能简单相加；消费强不保证股市涨，可能引发利率更高的预期。"]]},"i-34":{"title":"个人收入","line":"居民获得的工资、经营收入、财产收入、转移支付等汇总，帮助判断消费有没有收入支撑，而不只靠借钱。","points":[["怎么读","在BEA Personal Income and Outlays找 Personal income，再分 Compensation、Personal current transfer receipts 等来源。"],["怎么影响市场","居民花钱会成为企业营业收入，持续的实际收入又能支撑未来消费，所以数据会影响美股盈利预期。"],["常见误区","个人收入不是每个人平均拿到同样的钱；总量不显示分配，且名义增长要结合物价。"]]},"i-35":{"title":"可支配个人收入","line":"个人收入扣除个人经常税后的收入，是居民税后可用于消费或储蓄的钱；可支配不等于扣掉房租等生活费。","points":[["怎么读","在BEA找 Disposable personal income 和 Real DPI，核对是否人均；再看 Personal saving rate。"],["怎么影响市场","居民花钱会成为企业营业收入，持续的实际收入又能支撑未来消费，所以数据会影响美股盈利预期。"],["常见误区","可支配收入不是个人投资账户余额；减税会改变DPI，即使税前工资没变。"]]},"i-36":{"title":"个人储蓄率","line":"个人储蓄率（Personal Saving Rate）由美国经济分析局（BEA）按月随《个人收入与支出》报告发布，用来衡量美国整个居民部门当期税后可支配收入（DPI）在扣除个人消费支出、非房贷利息支出和经常性转移支付之后，剩余部分占可支配收入的百分比。","points":[["怎么读","拆解分子分母来源：同时读取同表中的可支配个人收入（DPI）增速与个人消费支出（PCE）增速，看储蓄率上升是来自收入增加还是支出减少。"],["怎么影响市场","传导链条并非储蓄率数字直接推升或打压资产价格，而是：储蓄率高低改变市场对居民后续消费韧性的判断→影响企业营收预期与美国GDP增长前景→进一步影响美联储对需求强弱及利率路径的权衡→反映在美债收益率、美元流动性与风险偏好上。"],["常见误区","把个人储蓄率误读为银行存款增长率，或者以为美股大涨、房价上涨会让当月个人储蓄率跟着上升。"]]},"i-37":{"title":"谘商会消费者信心","line":"谘商会消费者信心指数（Conference Board Consumer Confidence Index）由美国世界大型企业联合会（The Conference Board）按月发布，通过问卷调查美国居民对当前商业环境、就业岗位充裕度以及未来六个月收入与经济前景的主观评价。","points":[["怎么读","对比公布值、预期与前值修正：将总指数（Headline）与市场一致预期及上月修订后的终值并列比较，看总指数比预期高或低了多少个指数点，并留意上月数值的修订。"],["怎么影响市场","传导路径是：居民对就业与收入的信心变化→影响未来几个月的非必需品消费意愿与劳动力流动率→改变市场对经济软着陆或衰退的概率评估→牵动美联储利率预期与美债收益率，进而传导至股票估值和加密资产的风险偏好。"],["常见误区","把105点的指数读数误认为“105%的人有信心”，或者直接拿谘商会的105点去和密歇根大学信心指数的70多点比大小。"]]},"i-38":{"title":"密歇根大学消费者信心","line":"密歇根大学消费者信心指数（University of Michigan Consumer Sentiment Index）由密歇根大学社会研究所按月分“初值（Preliminary）”和“终值（Final）”两次发布，通过电话与网络问卷评估美国居民对个人财务状况、整体经济前景及大件商品购买条件的看法，并同步公布备受央行关注的1年期与5-10年期通胀预期。","points":[["怎么读","双线读取信心与通胀预期：先看总信心指数、现况与预期三个指数点读数，再看1年期和5-10年期通胀预期的百分比。"],["怎么影响市场","这条数据通过两条传导链影响市场：第一条是“居民财务信心→耐用品消费意愿→企业盈利预期”；第二条是“居民通胀预期百分比→影响员工要求涨薪的幅度与商家提价行为→直接牵动美联储对‘通胀预期是否脱锚’的警惕→改变美债收益率与降息路径”。"],["常见误区","把“指数点”与“通胀预期百分比”混淆，或者看报告时只盯总信心指数却漏看了往往更能引爆行情的通胀预期分项。"]]},"i-39":{"title":"消费者信贷","line":"消费者信贷由美联储委员会（Federal Reserve Board）按月发布，用来衡量美国居民部门尚未偿还的、不以房地产作抵押的消费债务总额及月度变化，主要分为信用卡等“循环信贷（Revolving）”与汽车贷款、学生贷款等“非循环信贷（Nonrevolving）”。","points":[["怎么读","拆解循环与非循环两大分项：分别查看Revolving与Nonrevolving的增减，判断借贷集中在大件耐用品还是日常刷卡。"],["怎么影响市场","传导链条是：居民信贷扩张或收缩→反映家庭借钱支撑消费的能力与意愿，以及商业银行放贷标准的松紧→影响零售企业营收预期与银行信贷资产质量→传导至美联储对金融条件松紧的判断、美债收益率及股票估值。"],["常见误区","把G.19消费者信贷当成美国家庭的全部负债，漏掉了占美国家庭债务大头的住房按揭贷款。"]]},"i-40":{"title":"居民贷款逾期率","line":"居民贷款逾期率（Household Loan Delinquency Rates）主要由美联储委员会发布，并常辅以纽约联储的《家庭债务与信贷季度报告》，用来衡量信用卡、汽车贷款、个人消费贷及住宅按揭贷款余额中未按合同期限定期还款的贷款占比。","points":[["怎么读","区分逾期率、核销率与转入率：核对表头看的是存量逾期占比（Delinquency Rate）、已注销坏账率（Charge-off Rate），还是纽约联储按季度公布的新转入逾期比例（Transition Rate）。"],["怎么影响市场","传导链条是：居民贷款逾期率持续上升→说明高利率或生活成本压力正在侵蚀家庭偿债能力→迫使居民削减后续非必需消费，同时迫使商业银行计提更多坏账拨备（Provision for Loan Losses）并收紧放贷标准→压缩企业营收预期与信贷流动性→压制股票估值及加密资产的风险偏好。"],["常见误区","只看逾期率下降就以为借款人财务好转，忽略了两个数学假象：一是银行把严重逾期的烂账直接核销，让分子变小；二是新增贷款快速扩张，让分母变大，这两种情况都会让比率看起来下降。"]]},"i-41":{"title":"新屋开工","line":"新屋开工（Housing Starts）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月联合发布，用来统计美国私人住宅建设项目中当月已经正式破土动工的住宅套数。","points":[["怎么读","对比公布值、预期与前值修正：把总开工年率套数、月环比百分比与市场预期及上月修订值放在一起对比，并留意抽样带来的较宽置信区间。"],["怎么影响市场","传导链条是：新屋开工增减→直接拉动或收缩建筑工人雇佣、木材铜材水泥等大宗建材采购，以及几个月后的家电家具消费→改变市场对固定资产投资与经济周期的判断→影响美联储对高利率是否已压制实体经济的评估与美债收益率→间接传导至美股与加密资产。"],["常见误区","把“季调年率140万套”误认为当月一个月就开工了140万套。"]]},"i-42":{"title":"建筑许可","line":"建筑许可（Building Permits）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月随《新住宅建设》报告同步发布，用来统计全美实行施工许可制度的地区内，地方政府当月批准新建私人住宅的套数。","points":[["怎么读","对比公布值、预期与前值修正：把当月建筑许可年率套数与财经日历预期值及上月修订值对比，并留意许可数据的抽样误差远小于开工数据。"],["怎么影响市场","传导链条是：建筑许可增减→提前1到3个月预示未来住宅开工、建筑业用工与上游建材订单的景气度→改变市场对未来GDP住宅投资与经济周期拐点的预期→影响美债收益率与美联储政策路径判断→间接传导至美股与加密资产的风险偏好。"],["常见误区","把“获得建筑许可”直接等同于“已经破土动工”甚至“已经盖好上市销售”，忽略了从拿证到动工、再到竣工往往横跨数月乃至一年以上，而且项目还可能被取消。"]]},"i-43":{"title":"成屋销售","line":"成屋销售（Existing-Home Sales）由全美房地产经纪人协会（NAR）按月发布，用来统计美国二手住宅在当月正式办完产权过户交割手续（Closing）的成交套数、待售库存及成交中位价。","points":[["怎么读","对比年率销量、预期与前值：读取季调年率销量及环比、同比变化，并与预期比较。"],["怎么影响市场","传导链条是：二手房交割量与周转率变化→直接带动房产中介佣金、按揭贷款发放、搬家装潢及家具家电等链条式消费，同时反映前1-2个月的按揭利率对居民换房流动性的挤压程度→影响市场对内需韧性与居住通胀环境的判断→传导至美债收益率、地产家装板块及整体美股与加密资产的风险偏好。"],["常见误区","把“已完成交割（Closing）”的成屋销售与“刚签合同（Contract Signing）”的新屋销售（第44课）放在同一个月横比，却没有考虑一到两个月的交割时差。"]]},"i-44":{"title":"新屋销售","line":"新屋销售（New Residential Sales，常称New Home Sales）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月联合发布，用来统计美国新建成的私人独栋住宅（New Single-Family Houses）在当月签订购房合同或收到买方定金的套数、待售库存及售价。","points":[["怎么读","对比公布值、预期、前值修正与置信区间：将当月年率销量与预期及前三个月修订值对比，并留意±12%到±18%的90%置信区间。"],["怎么影响市场","传导链条是：新屋签约量与待售库存变化→直接决定住宅建筑商的现金回笼速度、拿地开工意愿以及是否需要通过“贴息（Mortgage Rate Buydown）”或降价促销来去库存→进而影响未来的新屋开工（第41课）、建筑就业和建材家居订单→改变市场对房地产周期与经济增速的预期→通过美债收益率和风险偏好间接影响美股与加密资产。"],["常见误区","忽略新屋销售极宽的抽样误差与频繁的前值大修，把单月+8%的环比跳动当成板上钉钉的趋势反转。"]]},"i-45":{"title":"成屋签约销售","line":"成屋签约销售指数（Pending Home Sales Index，简称PHS）由全美房地产经纪人协会（NAR）按月发布，用来追踪美国二手住宅市场里买卖双方“已经签署购房合同、但尚未走完过户交割流程（Pending）”的交易活动变化。","points":[["怎么读","重点看月环比百分比与预期差：财经日历通常以“季调月环比变化（m/m %）”作为头条焦点，并对照前值修订。"],["怎么影响市场","传导链条是：当月按揭利率与挂牌房源变化→最先体现在买房人签合同的意愿上→提前1到2个月预示未来的成屋过户成交量、房产经纪收入、按揭放款及装修家具需求→改变市场对房地产景气与居民消费势头的判断→通过美债收益率和政策预期传导至美股与加密资产。"],["常见误区","把指数读数84点误读成“卖了84万套房”，或者以为“指数比2001年基准100低了16点就代表房价跌了16%”。"]]},"i-46":{"title":"Case-Shiller 房价指数","line":"标普Case-Shiller房价指数（S&P CoreLogic / Cotality Case-Shiller Home Price Indices）由标普道琼斯指数公司按月发布，采用经济学家Karl Case与Robert Shiller开创的“重复销售法（Repeat-Sales Method）”，专门追踪同一套独栋住宅在历史上前后两次或多次转手时的真实价格变化。","points":[["怎么读","区分全美指数与20城指数：找到U.S. National Index与20-City Composite两行，核对财经日历一致预期对应的是20城同比还是季调月环比。"],["怎么影响市场","传导链条是：同质独栋房价涨跌→改变美国家庭最大宗资产的账面财富效应（Wealth Effect）与房产净值抵押能力，同时影响银行按揭抵押品的违约安全垫→在中长期维度上传导至新签租约与CPI/PCE中的住房服务（Shelter/OER）通胀走势→进而改变美联储对长期通胀粘性与利率路径的判断→间接影响美债收益率、美股与加密资产。"],["常见误区","不知道Case-Shiller有“两个月发布滞后+三个月移动平均+过户比签约再晚一两个月”的三重时间延迟，误把5月下旬发布的数据当成5月当下的房价。"]]},"i-47":{"title":"FHFA 房价指数","line":"FHFA房价指数（FHFA House Price Index，简称FHFA HPI）由美国联邦住房金融局（Federal Housing Finance Agency）按月及按季度发布，同样采用“重复销售法”追踪同一套独栋住宅的价格变化，但它的基础数据来源于房利美（Fannie Mae）和房地美（Freddie Mac）两家政府支持企业收购或担保的符合标准（Conforming）按揭贷款记录。","points":[["怎么读","对比公布值、预期与前值修正：读取全美月度季调环比（m/m %）和同比（y/y %），并留意上月增速是否被修订。"],["怎么影响市场","传导链条是：中产按揭购房价格变化→直接决定两房及商业银行按揭贷款池的贷款价值比（LTV）与违约损失缓冲垫，并改变全美中产家庭的房产净值感受→影响消费信贷扩张能力与未来居住通胀预期→传导至美联储政策评估、按揭抵押债券（MBS）利差、美债收益率以及美股与加密资产风险偏好。"],["常见误区","不知道FHFA月度指数只统计“房利美和房地美符合贷款上限的按揭购房交易”，当高利率时期富人全现金买房占比飙升或豪宅领涨时，FHFA的读数就可能和整体房价走势出现偏差。"]]},"i-48":{"title":"MBA 抵押贷款申请","line":"MBA每周抵押贷款申请调查（MBA Weekly Mortgage Applications Survey）由美国抵押贷款银行家协会（Mortgage Bankers Association）于每周三上午发布，用来统计截至上周五的一周内，美国居民向商业银行、储蓄机构和房贷公司提交的独栋住宅按揭贷款申请数量变化。","points":[["怎么读","彻底拆开购房（Purchase）与再融资（Refinance）：不要只看Market Composite总指数，必须分别读取季调后Purchase周环比与Refinance周环比。"],["怎么影响市场","传导链条是：每周国债收益率与按揭利率涨跌→第一时间触发居民再融资或买房贷款申请的增减→提前数周预示下月的成屋签约销售（第45课）与新屋销售（第44课），同时通过再融资省下的月供改变家庭可支配现金流→影响市场对高利率向实体房地产传导速度的评估→间接作用于美债收益率、地产股及整体美股与加密资产风险情绪。"],["常见误区","把“综合申请指数上涨10%”直接解读成“买房需求大涨10%”，完全没看分项里到底是买房（Purchase）在涨，还是再融资（Refinance）在涨。"]]},"i-49":{"title":"抵押贷款利率","line":"房地美初级抵押贷款市场调查利率（Freddie Mac Primary Mortgage Market Survey，简称PMMS）由美国政府支持企业房地美（Freddie Mac）于每周四中午发布，用来公布美国最主流的“30年期固定利率按揭贷款（30-Year Fixed-Rate Mortgage）”及15年期固定按揭的全国平均利率水平。","points":[["怎么读","换算基点变化并对照10年期美债：算清本周利率变动了多少个基点（bp），并对照10年期美债收益率从上周四到本周三的变动。"],["怎么影响市场","传导链条是：通胀与货币政策预期推动10年期美债收益率及按揭利差（MBS Spread）变动→直接决定30年期按揭利率高低→改变买房家庭的每月还本付息额以及老房东换房的意愿→影响新屋与二手房销售、建筑开工及家居耐用品消费→反过来作用于美国经济增长与美联储政策权衡→传导至美股与加密资产。"],["常见误区","以为美联储FOMC宣布降息或加息当天，30年房贷利率就会同方向同幅度变动——其实30年房贷锚定的是10年期美债收益率，如果美联储降息当天10年期美债收益率因为通胀担忧反而上涨，房贷利率反而可能上升。"]]},"i-50":{"title":"NAHB 房屋建筑商信心指数","line":"NAHB房产市场指数由全美住宅建筑商协会（NAHB）按月发布，通过问卷调查全美独栋住宅建筑商对“当前新房销售状况”、“未来六个月新房销售预期”以及“潜在买家看房客流（Traffic）”三个维度的景气评价。","points":[["怎么读","对比公布值、预期与前值：把本月HMI总指数与财经日历预期值及上月前值对比，看HMI比预期高或低了多少点，并跟踪它连续几个月的方向。"],["怎么影响市场","传导链条是：按揭利率、建材土地成本与售楼处客流变化→第一时间改变独栋建筑商的景气信心→直接影响建筑商接下来几个月去申请建筑许可（第42课）、拿地破土开工（第41课）以及雇佣工人、采购建材的计划→改变市场对房地产投资周期与经济软着陆的判断→通过美债收益率和板块盈利预期传导至美股及加密资产的风险偏好。"],["常见误区","把HMI从45升到49误读成“建筑商普遍非常乐观”或“新房销量增长了4%”，忘了只要低于50就说明觉得生意差的建筑商人数依然多于觉得生意好的人数。"]]},"i-51":{"title":"美联储资产负债表","line":"美联储资产负债表由美联储委员会于每周四下午发布，完整列出美联储截至本周三的“资产端”与“负债端”。","points":[["怎么读","拆解资产端是证券变化还是贷款变化：查看Total Assets周变动，分清增减是来自国债/MBS到期缩表（常规QT），还是来自贴现窗口等紧急贷款激增。"],["怎么影响市场","传导链条是：美联储资产端买卖证券或投放贷款，叠加负债端TGA与逆回购的抽水放水→共同决定留在商业银行体系里的“银行准备金（Reserves）”多寡与货币市场隔夜资金松紧→影响美债期限溢价、回购市场融资成本（SOFR）与金融条件→进而改变股票估值折现率与加密资产的宏观美元流动性风险偏好。"],["常见误区","只看“美联储总资产（Total Assets）”一条线涨跌就高喊“重启QE放水了”，完全不拆开资产端看增加的是“买国债”还是“银行危机紧急贷款”。"]]},"i-52":{"title":"银行准备金","line":"存款机构准备金余额由美联储委员会在每周四的H.4.1报告及月度H.6报告中发布，用来统计全美商业银行及其他存款机构存放在美联储账户里的结算资金总额。","points":[["怎么读","用负债恒等式核查增减来源：对照同表的总资产（QT缩表）、TGA和ON RRP，算清本周准备金变动是由哪一项抽水或放水引起的。"],["怎么影响市场","传导链条是：银行准备金总规模及在大中小银行间的分布变化→决定银行间同业拆借与国债回购市场的资金充裕度→一旦准备金从“充裕（Ample）”滑向“稀缺（Scarce）”，银行就会惜借资金，导致隔夜担保融资利率（SOFR）相对美联储准备金利率（IORB）出现异常飙升→迫使对冲基金与做市商去杠杆抛售资产，进而对美联储形成停止缩表的压力→直接影响债市与风险资产。"],["常见误区","把“商业银行存在美联储的准备金（Reserves）”与“居民存在商业银行的存款（Deposits）”加在一起算总钱数，或以为散户买股票会直接花掉美联储的准备金。"]]},"i-53":{"title":"隔夜逆回购余额 ON RRP","line":"隔夜逆回购余额（Overnight Reverse Repurchase Agreements Facility，简称ON RRP）由纽约联储（Federal Reserve Bank of New York）在每个美国营业日中午操作后公布，用来统计货币市场基金（MMFs）、政府支持企业（GSEs）和银行等合资格机构，当天选择把闲置现金隔夜存放在美联储账上、以换取美联储名下国债作抵押并赚取固定逆回购利息的总金额。","points":[["怎么读","读取接受金额、参与家数与工具利率：记录Total Accepted、参与机构数以及当期Award Rate（如4.55%或5.30%）。"],["怎么影响市场","传导链条是：美联储调整利率或财政部增发短期国库券（T-Bills）→改变市场短债收益率相对ON RRP固定利率的吸引力→吸引货币基金把现金从ON RRP抽出来去认购财政部新发的短债→结果原本需要从商业银行准备金（第52课）里抽水去买国债的压力，被ON RRP这只“蓄水池缓冲垫”替银行挡下了→从而在美联储缩表（QT）期间保护了银行准备金不被迅速抽干→间接稳定了回购市场利率、美股估值与加密资产流动性环境。"],["常见误区","把中美央行的术语叫反——在中国人民银行语境里“逆回购”是央行向市场投放流动性，而在美联储（Fed）语境里，逆回购（ON RRP）是从交易对手那里回收现金。"]]},"i-54":{"title":"财政部一般账户余额 TGA","line":"财政部一般账户（TGA）是美国财政部设在美联储的官方现金结算账户，政府日常征收税款与发行国债募集的现金通常汇入该账户，而发放联邦福利、支付政府采购账单或偿还到期国债本息时资金则从该账户流出。","points":[["怎么读","逐项核对当日税收收入（Receipts）、财政支出（Withdrawals）以及公共债务发行与偿还结算净额，再把当前余额与财政部季度再融资文件中公布的季末现金目标对比。"],["怎么影响市场","在美联储资产负债表恒等式下，若其他负债项目不变，TGA余额上升会抽走商业银行体系的准备金，而TGA余额下降则会向银行体系注入准备金；但如果货币市场基金直接从隔夜逆回购（ON RRP）账户抽出资金认购新发行的短期国库券，ON RRP的下降就能缓冲甚至抵消TGA上升对银行准备金的抽水效应，进而改变短期融资的松紧和风险偏好。"],["常见误区","不能把TGA余额下降误读为政府实现财政盈余或无钱可用，也不能把TGA单日余额变动直接等同于联邦预算赤字增减，更不能脱离ON RRP和银行准备金，把TGA曲线直接叠在股票或加密货币走势图上看。"]]},"i-55":{"title":"M2 货币供应量","line":"M2货币供应量（M2 Money Stock）是美联储统计的广义流动性指标，汇总了实体经济中可直接用于支付的货币以及较容易转化为支付手段的近似货币资产。","points":[["怎么读","拆解流通中现金、活期与储蓄存款（M1分项）、小额定期存款及零售货币市场基金的各自变动；注意2020年储蓄存款重分类仅在M2内部调整了M1边界，并没有机械推高M2总量。"],["怎么影响市场","M2增速反映居民与企业的广义名义流动性环境：温和扩张有助于支撑消费需求与资产配置能力，但过快膨胀若伴随商品与服务供不应求，可能推升通胀压力并促使央行维持高利率；而加密市场与美股除了受美国本土M2环境影响外，还受到全球美元融资、机构货币基金、衍生品杠杆及监管政策的共同驱动，单看一条M2曲线无法准确判断市场的转折时点。"],["常见误区","别把M2、美联储总资产、商业银行准备金三者混淆；同时牢记2020年5月储蓄存款重分类只是在M2内部将储蓄存款划入M1，并未机械放大M2总量，并留意季节调整和更高频的数据。"]]},"i-56":{"title":"商业银行存款","line":"商业银行存款统计美国境内商业银行资产负债表上对储户和企业承担的存款总额，是评估银行体系日常资金来源是否稳定的高频窗口。","points":[["怎么读","分别查看国内大型银行（前25家）、国内中小型银行以及外资银行相关分支机构的存款分项变化，判断当周变动是全行业普遍流出，还是资金在银行之间避险搬家。"],["怎么影响市场","存款是商业银行最核心的低成本融资来源：若存款持续外流，银行可能被迫提高揽储利率、借入成本更高的批发资金甚至收缩信贷投放，从而收紧实体经济与股市的信用环境；对加密市场而言，除了受宏观信贷松紧传导外，服务加密行业的特定银行若出现存款剧烈波动，也可能扰乱法币出入金渠道和市场对稳定币储备的信心。"],["常见误区","切勿脱离季节性税款收缴、季末考核和报表底部并购重分类脚注，仅凭单周未季调存款下降就断定发生银行业挤兑；也不要把资金转入货币市场基金误当成钱消失了。"]]},"i-57":{"title":"商业银行贷款","line":"商业银行贷款统计美国商业银行资产负债表上已经发放但尚未收回的存量贷款与融资租赁总额。","points":[["怎么读","拆解工商业贷款（C&I）、商业与住宅房地产贷款及信用卡消费贷款的各自走势，并查阅报表底部脚注（Footnotes），排查是否有非银行机构并购、贷款证券化出售或大额坏账核销导致的账面跳变。"],["怎么影响市场","银行信贷是企业扩产投资与居民大宗消费的核心资金推手，但贷款余额上升既可能源于经济景气时的健康投融资扩张，也可能源于流动性危机初期企业出于防御心理集中提取既有循环授信额度（Revolving Credit Lines）；反之，贷款余额收缩既可能是高利率下借款人不想借，也可能是银行担心坏账不敢借。"],["常见误区","不能把账面贷款余额短期跳升简单等同于经济繁荣，危机初期企业防御性提取循环授信额度同样会推高C&I贷款余额；还要查看脚注里的坏账核销和资产转移。"]]},"i-58":{"title":"SLOOS 银行信贷标准调查","line":"高级贷款专员意见调查（SLOOS，Senior Loan Officer Opinion Survey on Bank Lending Practices）是美联储通常每季度开展一次的定性问卷调查，直接向美国本土大型与中小型商业银行及外资银行驻美分支机构的信贷主管提问：过去三个月贵行放贷审批门槛是收紧了还是放宽了？","points":[["怎么读","按大中型企业与小企业工商业贷款（C&I）、商业地产贷款（CRE）、住宅按揭以及信用卡和汽车消费贷分项核对，看供给收紧和需求走弱是否集中在某几类贷款。"],["怎么影响市场","SLOOS往往领先于实际违约率与贷款余额变化：当多数银行同步收紧放贷标准并提高利差要求时，抗风险能力较弱的企业和家庭将更难获得展期或新增融资，进而抑制未来几个季度的资本开支、招聘与消费；而信贷需求大幅下滑则直接反映高利率或经济前景不明对实体借贷意愿的压制。"],["常见误区","别把净收紧比例下降误读为银行已经开始放松信贷，只要净收紧读数为正，信贷门槛就是在上一季基础上继续叠加收紧；也不要把这些问卷百分比和实际贷款利率混为一谈。"]]},"i-59":{"title":"SOFR 融资利率","line":"担保隔夜融资利率（SOFR，Secured Overnight Financing Rate）是由纽约联储与美国财政部金融研究办公室（OFR）共同编制发布的基准利率，汇总衡量金融机构以美国国债作为抵押品、在回购市场（Repo Market）借入隔夜美元现金的实际成交利息成本。","points":[["怎么读","将当日SOFR以及75%、99%高分位利率与美联储政策管理利率及前一日SOFR进行对比，判断利率变动是跟随美联储加息降息的正常政策平移，还是回购市场真正出现了融资压力。"],["怎么影响市场","SOFR直接挂钩数万亿美元的企业浮息贷款、货币市场工具与利率衍生品定价：在正常时期，SOFR紧贴美联储政策利率走廊平稳运行；但当国债结算激增、银行准备金偏紧或季末资产负债表约束导致回购市场现金供不应求时，SOFR可能异常跳升并突破政策利率走廊，迫使高杠杆对冲基金与做市商平仓去杠杆，进而波及股票和加密资产。"],["常见误区","别把有国债抵押的SOFR与无抵押的联邦基金有效利率（EFFR）混淆，记住单日SOFR采用的是成交量加权中位数而非算术平均，也不要把季末单日的跳升外推成即将爆发的危机。"]]},"i-60":{"title":"美联储贴现窗口借款","line":"美联储贴现窗口借款是合资格存款类金融机构以合格贷款或证券作为抵押品，直接向美联储申请短期流动性周转的官方常设工具。","points":[["怎么读","逐行拆解Primary credit、Secondary credit、Seasonal credit以及任何其他专项流动性工具的余额变化，别把不同性质的央行借贷工具简单混同。"],["怎么影响市场","贴现窗口借款在金融市场中具有“双刃剑”信号意义：一方面，央行提供充足的抵押借款能防止银行在面临存款流失时被迫以跳楼价抛售国债或信贷资产，起到稳定金融体系的作用；另一方面，若一级信贷余额在非节假日或非测试期突然成倍暴增，常意味部分银行在同业回购市场难以按正常成本借到钱，从而暴露银行业潜在的存款流失或流动性紧张，说明这些银行在市场上借钱变难了。"],["常见误区","别把流动性周转需求（Liquidity）与资不抵债（Solvency）混淆，贴现窗口借款余额代表的是有抵押的短期融资额而非银行的资本金亏损缺口；也不要把应急托底借款等同于央行主动放水。"]]},"i-61":{"title":"美国国债拍卖结果","line":"美国国债拍卖结果（U.S. Treasury Auction Results）记录美国财政部在一级市场公开招标发行新国债时的最终成交定价与认购分布情况。","points":[["怎么读","读取最高中标收益率（High Yield）与投标倍数（Bid-to-Cover），并立即与拍卖截止时间的同期限When-Issued（WI）预发行收益率相减：若中标收益率高于WI收益率即为出现“尾差”，低于WI收益率则为“穿价”。"],["怎么影响市场","美债拍卖是一级市场检验无风险利率承接力的试金石：若中长期国债拍卖需求疲软，往往会直接推升二级市场美债收益率，进而抬高美股估值的折现率并收紧加密市场的美元杠杆融资环境；但也需注意，若拍卖前美债已大幅下跌，符合预期的平淡拍卖未必引发新一轮抛售，相反，认购踊跃的拍卖可以平息利率波动，但要分辨强劲买盘是正常的长期配置需求，还是市场动荡时的避险潮。"],["常见误区","不能只看投标倍数（Bid-to-Cover）高低就断定拍卖好坏，也不能拿本次中标收益率与上月绝对数值直接比大小，核心必须对比拍卖截止刻的When-Issued收益率以及一级交易商的被动获配占比。"]]},"i-62":{"title":"国债净发行规模","line":"国债净发行规模（Net Marketable Treasury Borrowing）衡量美国财政部在特定期间内通过发行可流通国债向私人市场新筹集的资金总额，减去同期归还到期旧债本金后的净新增借款额。","points":[["怎么读","同时核对公告下方附带的“季末TGA现金余额假设（Assumed End-of-Quarter Cash Balance）”，并查看周三发布的再融资声明中短期国库券（Bills）与中长期附息债（Coupons）各自的拍卖规模安排。"],["怎么影响市场","净发行规模及其期限结构直接决定债券市场供求与流动性走向：若财政部大幅超预期增发10年期、30年期等中长期附息国债，机构投资者往往要求更高的期限溢价（Term Premium），从而推升长端美债收益率并压制美股与加密资产估值；反之，若净增发主要集中在短期国库券（T-Bills），且收益率具吸引力，货币市场基金往往会从美联储隔夜逆回购（ON RRP）中抽出闲置资金来认购短票，未必会明显抽走银行准备金。"],["常见误区","别把总发行额（Gross Issuance）误当成净抽水额（Net Borrowing），也要分清国债拍卖日（Auction Date）与实际资金交割的结算日（Settlement Date）；同时记住净借款额 = 财政赤字融资需求 + TGA期末现金余额变动，其中赤字是主体，TGA变动是调节项。"]]},"i-63":{"title":"美国财政预算赤字","line":"美国财政预算赤字衡量联邦政府在特定月份或财年内，总财政支出（Outlays）与总财政收入之间的收支差额：当期支出大于收入即为财政赤字（Deficit），收入大于支出则为财政盈余（Surplus）。","points":[["怎么读","分别读取当月财政总收入（Receipts）、总支出（Outlays）、当月赤字/盈余净额以及本财年迄今累计值，并查看报告附注，看月初是否因周末或节假日挪动了付款。"],["怎么影响市场","财政赤字对金融市场具有双重作用机制：一方面，从实体经济角度看，政府赤字支出直接转化为居民收入和企业订单，在经济放缓期能托底总需求与企业盈利；另一方面，从金融市场供给角度看，持续且超预期的庞大结构性赤字意味着财政部必须靠大规模增发国债来填补缺口，可能推升通胀预期、抬高长端美债期限溢价与无风险利率，进而对美股高估值板块与加密市场形成折现率压制。"],["常见误区","别把财政赤字误认为政府债务违约，也不要把4月报税季的常规单月财政盈余当成长期财政扭亏为盈；同时，由于存在TGA现金账户缓冲，单月财政赤字和当月发债量之间不是一一对应的关系。"]]},"i-64":{"title":"加密 ETF 每日资金流量","line":"加密ETF每日资金流量（Crypto ETF Daily Net Flows）统计现货比特币或以太坊等交易所交易基金（ETF）在每个美股交易日内，因基金份额净申购（Net Creations）与净赎回（Net Redemptions）所对应的资金净流入或净流出金额。","points":[["怎么读","逐列查看各家现货ETF分项（如IBIT、FBTC、ARKB、BITB、GBTC等）与最右侧的全市场合计列（Total），务必等待当日所有主要基金全部披露完毕后再引用Total总数，不要把尚未披露的空白格当成零流量。"],["怎么影响市场","现货加密ETF的授权参与人（AP）在净申购时通常需要通过现金或实物机制在现货市场采购对应的底层加密货币，净赎回时则需卖出底层资产以兑付现金，因此连续多日的全行业大额净流入往往提供真实的现货买盘支撑并提振市场情绪；但需注意，部分机构买入现货ETF的同时可能在CME期货市场做空同等规模合约以赚取无风险基差收益，且不同费率ETF之间的存量资金搬家也会干扰单只基金的读数。"],["常见误区","别把二级市场ETF股票当日成交额（Trading Volume）与一级市场份额净申赎资金流（Net Flows）混淆，切勿把币价上涨带来的AUM市值膨胀当成净流入，也不要在主要发行商全部披露前引用当天不完整的合计数。"]]},"i-65":{"title":"稳定币定期储备与鉴证报告","line":"稳定币定期储备与鉴证报告（Stablecoin Reserve and Attestation Reports）是由锚定法币的稳定币发行商定期披露的储备资产明细说明，以及由独立第三方会计师事务所出具的鉴证报告（Attestation Report）。","points":[["怎么读","读取截至该时点已发行流通的稳定币总负债金额（Tokens in Circulation / Liabilities）与储备资产总价值（Total Reserve Assets），验算储备资产是否大于或等于流通负债，并重点拆解储备资产构成：现金及银行存款、3个月内到期的美国国库券（U.S. Treasury Bills）、隔夜国债逆回购协议各自的占比，以及任何高风险或流动性较差的贷款、商业票据和其他资产。"],["怎么影响市场","法币稳定币是加密市场最核心的现货计价媒介、交易结算工具与衍生品履约抵押品抵押物：充足、高流动性且透明的储备结构能维系1:1锚定信心；反之，若报告暴露出储备存在资金缺口、高风险非流动资产占比过高、严重期限错配或托管银行出现兑付危机，极易触发稳定币二级市场脱锚（Depeg）与集中挤兑赎回，并可能引发整个加密市场被迫去杠杆。"],["常见误区","别把针对特定时点储备声明的“第三方鉴证（Attestation）”等同于对公司整体偿付能力与合规性的“全面财务审计（Full Audit）”，也不要只看100%以上的覆盖率，而不细看底层资产的流动性、期限结构和托管情况。"]]},"i-66":{"title":"美联储利率决议","line":"美联储利率决议（Federal Reserve FOMC Rate Decision）由美国联邦公开市场委员会（FOMC）按年度日程于美东时间周三下午14:00发布政策声明，14:30举行美联储主席新闻发布会，并在3月、6月、9月、12月季末例会同步公布《经济预测摘要（SEP）》与利率点阵图（Dot Plot）。","points":[["怎么读","读取季度SEP与点阵图：查看19位官员对今年、明年利率预测的中位数（Median Dot）移高还是移低了多少基点，并同时看GDP、失业率和核心PCE的预测。"],["怎么影响市场","传导链条是：FOMC调整当期目标利率、缩表速度及点阵图/声明措辞→直接改变联邦基金期货与2年期、10年期美债收益率对未来利率路径的定价→改变企业发债借贷成本、按揭利率以及股票估值模型里的分母→同时通过美德、美日利差驱动美元指数（DXY）强弱→进而全面传导至美股与加密资产的流动性及风险偏好。"],["常见误区","只看财经快讯弹窗标题“美联储降息25基点”就冲进去买，完全不知道会前市场早就100%消化了这次降息，而点阵图其实拿掉了未来的降息次数。"]]},"i-67":{"title":"欧洲央行利率决议","line":"欧洲央行利率决议（ECB Monetary Policy Decision）由欧洲中央银行管理委员会（Governing Council）按日程于法兰克福时间周四下午14:15发布政策声明，14:45由欧洲央行行长举行新闻发布会，并在3月、6月、9月、12月季度会议同步公布欧元区宏观经济预测（Staff Projections）。","points":[["怎么读","检查季度通胀与增长预测（3/6/9/12月）：查看ECB工作人员对今年、明年及后年欧元区HICP总体通胀、核心通胀及GDP增速预测的上调或下调。"],["怎么影响市场","传导链条有两条互相博弈的路径：第一条是“全球利率与流动性协同路径”——ECB降息或宽松→拉低德国国债（Bunds）等欧洲债券收益率→通过跨大西洋债券套利拉低美债收益率并改善全球融资环境；第二条是“汇率与美元指数路径”——因为欧元在美元指数（DXY）篮子里独占高达57.6%的最大权重，一旦ECB比美联储明显更鸽派→欧元兑美元（EUR/USD）往往下跌、直接推升美元指数DXY走强→而强势美元常对以美元计价的大宗商品、跨国美股海外利润折算及加密资产形成压制。"],["常见误区","看财经日历时分不清欧洲央行的三行利率数字，甚至在ECB实施框架调整缩窄MRO与DFR利差时，误把技术性的操作框架调整当成政策冲击。"]]},"i-68":{"title":"英国央行利率决议","line":"英国央行利率决议（Bank of England MPC Rate Decision）由英格兰银行货币政策委员会（Monetary Policy Committee，简称MPC）按日程于伦敦时间周四中午12:00发布，同步公布《货币政策摘要与会议纪要（Minutes）》，并在2月、5月、8月、11月季度例会一并发布包含通胀与GDP预测的《货币政策报告（MPR）》及行长记者会。","points":[["怎么读","对比投票分裂与市场预期：财经日历不仅有对利率的预期，还有对“加息-不变-降息”具体票数的预期，例如预期0-7-2而实际是0-5-4，数一数有几位委员改变了立场。"],["怎么影响市场","传导链条是：MPC利率决定、投票比分变化与季度MPR通胀预测→直接驱动英国金边债券（Gilts）收益率与英镑兑美元汇率波动→通过全球发达国家主权债联动影响美债与欧债收益率，并影响跨国企业英镑收入折算→间接传导至美股与加密资产的风险偏好。"],["常见误区","只看“英国央行维持利率不变”的标题就关掉页面，完全漏看了同秒发布的会议纪要里“投票比分从8:1变成5:4”的重磅鸽派转向信号。"]]},"i-69":{"title":"日本央行利率决议","line":"日本央行利率决议（Bank of Japan Monetary Policy Decision）由日本银行（BOJ）政策委员会按日程在为期两天的会议结束后公布，下午由日本央行行长举行记者会，并在1月、4月、7月、10月季度会议同步发布《经济与物价形势展望报告（Outlook Report）》。","points":[["怎么读","读取隔夜拆借利率目标与购债安排：确认无担保隔夜拆借利率引导目标变动了多少基点，投票是几比几，以及月度购债计划有没有调整。"],["怎么影响市场","传导链条是：日本央行意外加息、削减购债或释放鹰派加息信号→推升日本国债（JGB）收益率并缩小美日利差→驱动日元迅速升值→导致此前“借低息日元、买高息美元或高风险资产”的全球套息交易（Carry Trade）出现严重汇兑亏损与追加履约抵押品通知→迫使杠杆基金在东京和欧美交易时段集中抛售美股与加密资产来偿还日元负债。"],["常见误区","看反“美元兑日元（USD/JPY）”汇率报价的方向——USD/JPY从155涨到160代表1美元能换更多日元，而USD/JPY从150跌到135才代表日元升值。"]]},"i-70":{"title":"EIA 原油库存","line":"EIA每周原油库存（EIA Weekly Crude Oil Inventories）由美国能源信息署（U.S. Energy Information Administration）在每周三美东时间10:30发布的《每周石油状况报告（Weekly Petroleum Status Report）》中公布，用来统计截至上周五的美国商业原油库存总量及周度增减桶数。","points":[["怎么读","对比公布值、市场预期与前一日API倾向：把商业原油库存周变化与分析师一致预期对比，看实际值比预期多或少了多少百万桶。"],["怎么影响市场","传导链条是：商业原油与成品油库存意外去库或累库→直接推动WTI与布伦特原油期货价格涨跌→通过两条相反路径传导至大盘：一方面直接改变能源板块的盈利预期；另一方面通过汽油与柴油价格改变美国月度CPI总体通胀率、消费者日常出行账单以及市场对美联储利率路径的担忧→进而影响美债收益率、美股大盘及加密资产风险偏好。"],["常见误区","只盯第一行“商业原油库存变化”，完全不看同表下面的“汽油库存、柴油库存和炼厂开工率”，忽略了可能被汽油、馏分油库存的增加或炼厂开工率的变化所抵消。"]]},"i-71":{"title":"EIA 天然气库存","line":"EIA每周天然气库存（EIA Weekly Natural Gas Storage Report）由美国能源信息署（U.S. Energy Information Administration）于每周四美东时间10:30发布，用来统计截至上周五的美国本土48州（Lower 48）地下储气库中可随时提取使用的“工作天然气（Working Gas）”存量及周度净注气或提气变化。","points":[["怎么读","对比周度净变化（Net Change）与市场预期：将当周全美（Lower 48）净变化Bcf与分析师一致预期对比，看本周注气或提气量比预期多或少了多少Bcf。"],["怎么影响市场","传导链条是：天气冷暖、液化天然气（LNG）出口装船量及干气产量变化→决定当周天然气的净注入或净提取量→直接冲击美国Henry Hub天然气期货价格及公用事业、电力、化肥化工企业的燃料成本→进而通过居民电费与燃气账单影响CPI能源分项与通胀预期→间接传导至美债收益率、美股与加密资产。"],["常见误区","在冬天1月份看到EIA公布“-150 Bcf”就惊呼天然气库存暴跌要大涨——不知道冬天全美都在烧气取暖，每周库存本来就是负数，如果市场原本预期提气180 Bcf，实际只提了150 Bcf，反而说明库存比预期更宽裕。"]]},"i-72":{"title":"美债收益率与收益率曲线","line":"美债收益率是全球风险资产定价的“地心引力”。","points":[["怎么读","再算10Y-2Y利差：用10年期收益率减去2年期收益率，正值代表正常向上倾斜，负值代表收益率曲线倒挂。"],["怎么影响市场","10年期美债收益率常被视为全球无风险折现率的分母。"],["常见误区","把“收益率曲线倒挂”当成股市立刻暴跌的做空按钮：倒挂只是历史上的宏观领先观察指标，从出现倒挂到经济真正衰退往往间隔6至24个月不等，且期间股市完全可能继续上涨。"]]},"i-73":{"title":"美元指数 DXY","line":"美元指数（DXY）是衡量美元相对于一篮子外币强弱的温度计。","points":[["怎么读","交叉核对美联储广义美元指数（DTWEXBGS）：若关注人民币或新兴市场股市资金流，不能只看缺少亚洲新兴货币的DXY，需同步查看贸易加权的广义美元指数。"],["怎么影响市场","第一，计价效应：黄金、原油、铜等国际大宗商品及比特币以美元计价，美元指数走强会使非美买家购买成本上升，往往对大宗商品价格形成压制；第二，跨国企业折算：标普500成分股有近三成至四成收入来自海外，强美元会导致海外利润折算回美元时产生汇兑缩水；第三，新兴市场资金流：强美元伴随高美债利率时，容易引发资金从港股、A股等新兴市场回流美元资产。"],["常见误区","以为DXY代表美元对全世界所有货币的汇率：DXY是1973年设计的老篮子，里面完全没有人民币、澳元、墨西哥比索或韩元，近六成权重其实是欧元的镜像。"]]},"i-74":{"title":"VIX 波动率指数","line":"VIX常被媒体渲染为“恐慌指数”，但它并不是靠问卷调查出来的心理指标，而是用标普500指数期权（见本站「期权入门」一课）的真实真金白银报价算出来的未来30天预期波动幅度。","points":[["怎么读","区分平静期与压力期：VIX长期在12至20区间运行代表市场定价平稳；突破30通常代表机构对冲需求急剧升温；但低VIX只代表当前期权便宜，不代表未来绝对安全。"],["怎么影响市场","机构投资者持有庞大的美股现货多头，当宏观风险加剧或市场急跌时，机构会涌入期权市场大举买入标普500看跌期权（Put）进行尾部风险对冲，直接推高期权隐含波动率与VIX读数。"],["常见误区","误以为VIX本身可以像股票一样直接买入并长期持有等崩盘：VIX现货不可交易，而跟踪VIX期货的ETF在平时“近低远高”的升水结构（Contango）下每月移仓都会高买低卖，长期持有净值极易磨损殆尽。"]]},"i-75":{"title":"信用利差","line":"信用利差是债券市场给企业违约风险定的“保费差价”。","points":[["怎么读","拆解利差变动是由谁驱动的：利差走阔可能是因为企业债被抛售（收益率大涨），也可能是因为避险资金疯抢美债（美债收益率暴跌），需结合美债走势一起看。"],["怎么影响市场","股票投资者容易被乐观叙事吸引，而债券持有人拿的是固定利息、最怕本金违约。"],["常见误区","把“利差走阔（上涨）”当成利好股市：信用利差与VIX类似，是反向风险指标——利差数字越往上涨（走阔），说明企业借钱越难、违约风险越高，对股市是利空而非利好。"]]},"i-76":{"title":"中国 CPI","line":"中国CPI是度量国内居民日常购买商品和服务价格水平变动的核心通胀指标。","points":[["怎么读","重点看“核心CPI同比”与“服务价格”：核心CPI排除了猪肉和油价噪音，若核心CPI连续回升且服务价格在节假日带动下走强，才代表居民消费意愿真实回暖。"],["怎么影响市场","CPI直接关系到货币政策空间与企业名义利润率。"],["常见误区","每年1月或2月看到CPI同比忽高忽低就以为通胀失控或通缩恶化：忽略了农历春节在公历1月和2月之间移动造成的“春节错月基数效应”，看1–2月合计均值才能还原真相。"]]},"i-77":{"title":"中国官方制造业 PMI","line":"中国官方制造业PMI是每月最早公布（月末当天就出当月数）的宏观经济“先遣哨兵”。","points":[["怎么读","拆解“新订单减生产”与“新出口订单”：若生产指数高（>52）但新订单指数低（\u003c49），说明工厂在产但需求不足，可能面临产成品库存积压；若新订单高于生产，说明需求主动拉动复苏。"],["怎么影响市场","由于工业增加值、社融、进出口等官方硬数据要到次月中旬才陆续披露，每月最后一天上午公布的官方PMI直接决定了市场对当月中国经济景气度的第一印象。"],["常见误区","看到官方PMI与财新PMI一高一低就怀疑其中一个是假数据：两者的样本池容量（3200家 vs 650家）、企业规模结构（大中型国企重工 vs 沿海中小民企出口）和季调方法本来就不同，背离恰恰反映了大型企业与中小微企业的真实冷热温差。"]]},"i-78":{"title":"社会融资规模","line":"如果只看银行新增贷款，你会漏掉政府发债、企业发债和股票融资等庞大的资金渠道。","points":[["怎么读","拆解“成色结构”：在同日公布的金融统计报告中，对比“企（事）业单位中长期贷款”（代表企业真实固定资产投资与扩产）与“短期贷款及票据融资”（银行为了凑信贷额度而拿低息票据冲量）的占比，并观察“住户中长期贷款”（基本对应个人房贷）是否回暖。"],["怎么影响市场","中国经济对信用周期高度敏感，“社融存量同比增速”和信贷结构被视为A股、港股及国内商品期货的领先或同步风向标。"],["常见误区","拿本月社融增量跟上个月比（看环比）：中国信贷投放受银行年度考核与季度额度控制，1月冲高、2月回落、3月季末再冲高、4月再回落是持续多年的固定季节性规律，看环比必被误导，必须看“同比多增/少增”和“存量同比增速”。"]]},"i-79":{"title":"LPR 贷款市场报价利率","line":"在中国，新闻里常说的“降息”往往涉及好几个利率：央行给商业银行的批发政策利率（如7天逆回购利率），以及商业银行给企业和居民放贷的零售基准——贷款市场报价利率（LPR）。","points":[["怎么读","看“非对称调整（1Y vs 5Y+）”：对比1年期和5年期以上LPR的下调幅度——若1年期不变而5年期以上单独下调，或5年期以上降幅大于1年期，说明政策重心在于托底房地产与中长期投资；反之若只降1年期，则侧重短期企业减负。"],["怎么影响市场","LPR直接决定实体经济与购房家庭的利息支出负担。"],["常见误区","以为每月20日LPR一下调，自己下个月的房贷月供就会立刻跟着降：存量房贷合同都设有“重定价周期”（以前多为1年，2024年11月起可与银行协商调整为3个月、6个月或1年），只有到了合同约定的“重定价日（如每年1月1日或放款对应日）”，你的房贷利率才会按最新一期的5年期以上LPR更新。"]]}};
